window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_040"]={"n":"杨玉衔","dyn":"清","poems":[{"t":"扫花游 丁卯孟春海上坐雨作","f":"古风","c":["买春紫陌。","拥万马涛来，弄潮人喜。","问津那处。","怪支机赠石，汉槎楫舣。","浪杳云沈，为恁鳞鸿又误。","放灯里。","怕蜃雾幻楼，昏到庭户。","天醉谁与语。","任蝶浪蜂狂，恣情飞舞。","待风唤去。","奈园林遍绿，乱莺无主。","刬地残红，恐惹啼鹃更苦。","正延伫。","碎羁魂、暮众零杵。"]},{"t":"蓦山溪 寄题听枫园，和彊师酬叔问韵","f":"古风","c":["词仙卜筑，例远尘嚣市。","吟罢古藤阴，下沧洲、琴携绿绮。","白沤波暖，吟侣集江鸥，樵风径，蕙风天，空谷跫然喜。","霜虹钟讯，惯泊枫樯地。","唱到折红梅，满吟壶、楚声能继。","听风听水，卸却素馨帆，五柳侧，四桥边，又办听秋计。"]},{"t":"眼儿媚 和彊师韵","f":"古风","c":["舞衣收箧罢薰篝。","欢事分都休。","最无聊赖，瞒伊心绪，辄上眉头。","嫦娥不管人憔悴，今夕又当楼。","人閒何世，除非无月，我始无愁。"]},{"t":"倦寻芳 和彊师韵","f":"古风","c":["檐阴阁雨，帘隙梳烟，庭户催晚。","绕树归鸦，戢戢欲栖还散。","西崦斜阳鶗鴂苦，东风残信蘼芜怨。","问天涯、王孙何处，春随人远。","卜心事、灯花无语，百感孤单，鸳被羞展。","陡忆前欢，已等弃余秋扇。","客路歧多关塞黑，长门事去文章残。","梦方圆，又丛钟、声声惊断。"]},{"t":"无闷 西湖闻蝉","f":"古风","c":["一棹西泠，苍翠四合，中有幽人独语。","怯御道官槐，咽寒高处。","日暮秋山驿路。","莫认是、临歧阳关谱。","抱故宫红叶，寻消问息，几经风露。","谁诉。","甚凄楚。","岂懊恼西风，尽情倾吐。","算曾蜕初衣，也緌冠素。","自怨齐宫鬓薄，奈还有、歌声招人妒。","算绝调、弦谱中郎，毕竟知音迟暮。"]},{"t":"庆春宫 夏日西湖旅寓，读海绡人日谒虞仲翔先生祠作，感而继声","f":"古风","c":["堂迥人遥，幢虚云补，古今代谢堪惊。","战垒凭花，游裙怜草，菜羹谁荐芳馨。","南鸿归梦，空扪历、危楼上层。","金尊愁对，迁客骚人，一例飘零。","逋仙祠宇西泠，几树梅花，同此凄清。","浅水吟香，禅关读易，有缘猿鹤同听。","世途安处，湖波稳、扁舟叶轻。","余生都付，老我苍山，吊客青蝇。"]},{"t":"双双燕 除夕，和梦窗韵","f":"古风","c":["避嚣守岁，有檐竹临风，夜深敲户。","沈檀自爇，翠缕拂帘千度。","东壁欢呼博簺，好春在、红楼深处。","萧然斗室琴书，独被牢愁羁住。","慵举。","依梁倦羽。","芳讯报初番，酿寒花雨。","九衢灯火，一任燕莺歌舞。","多少痴呆意绪，待持向、东君分诉。","薄酒不温，空负啭年莺语。"]},{"t":"三殊媚·和海绡闰海明韵","f":"古风","c":["飞花萦步绮。","问东风、春城几人归思。","万里关山，盼南天、归雁高楼重倚。","缥缈鹃声，莫误认、瑶池鸟使。","奈曲水裙遥，省识无人，商量花事。","更感韶光逝水。","看宿雨桃花，送春悬泪。","旧约鞦韆，拚晓梦消磨，被莺呼起。","病怯扶阑，消受惯、薄棉天气。","门外传来消息，青梅有子。"]},{"t":"满江红 草原上无主翁仲","f":"古风","c":["捐弃谁怜，斜阳下、无言独立。","人疑是、长安古道，卧驼荆陌。","高冢夷为鸣屐路，丰碑借作支床石。","怎翟公、罗雀已无门，犹留客。","钟鼓室，他人入。","松楸地，灵狐宅。","问邱山华屋，忍谈今昔。","野火更防身后劫，鬼雄难护耕余域。","正摩挲、欲与话桑沧，山风急。"]},{"t":"卜算子 和水云","f":"古风","c":["泪眼不曾晴，化作宵来雨。","六曲屏山万里程，有梦无寻处。","羞学倚墙花，分等沾泥絮。","愿屑香尘逐马蹄，长傍郎边去。"]},{"t":"柳梢青 和水云","f":"古风","c":["灯蕊摇青，扉苔锁绿，阒寂音尘。","月落尊空，人遥瑟怨，挨过黄昏。","天涯芳草斜曛。","数客路、从头细温。","欲理新愁，余酲犹殢，鬟亸颓云。"]},{"t":"惜红衣 寄怀朱聘三太史蓟门，用白石韵","f":"古风","c":["鬓怯经霜，戈穷返日。","无多心力。","瀛海罡风，吹朱倏成碧。","扶摇路阻，浑一梦、天河乘客。","枯寂。","人海閒鸥，老苍波栖息。","寻常巷陌。","联袂看花，游鞋落红藉。","南云铩羽去国。","阻溟北。","咫尺九天星斗，望绝骖鸾扪历。","渺长安万里，犹见月梁颜色。"]},{"t":"殢人娇 风雨满湖，凄然独酌","f":"古风","c":["泼墨模糊，把个明湖渲染。","且莫道、西施妆澹。","苎萝金粉，付云霾烟掩。","游船散，情丝漫牵湖缆。","故国沈沈，旅怀黯黯。","莺啼处、算无拘检。","声声警我，勿恋姬垆清簟。","待晴去，又怕夕阳红敛。"]},{"t":"高阳台 小青墓，和彊师朝云墓韵","f":"古风","c":["桃叶波荒，柳枝春去，愁云影里西湖。","青冢谁铭，鸳鸯瓦在人徂。","分明宝马香车路，奈烟寒、不绿平芜。","订莺邻、苏小归环，相望城隅。","昙花不入修罗劫，看朝云夕散，天窘髯苏。","电泡须臾，参来一穿牟珠。","担愁病骨经霜怯，守残镫、人似山孤。","更无多、僵后蚕丝，紬罢凄如。"]},{"t":"诉衷情 为人题秋镫课子图卷","f":"古风","c":["丸熊画荻课宁馨。","春暖尚萱庭。","展卷如对环佩，妒煞失巢莺。","思我母，伴儿镫。","月三更。","于今麦饭，阻隔天涯，廿载清明。"]},{"t":"八声甘州","f":"古风","c":["倩千蕖、捧出界庄严。","楼台乱苍烟。","溯当年花竹，中兴鼙鼓，谪宦流连。","满地夕阳红处，碧草又芊芊。","我濯宜清否，问水无言。","万事废兴何定，纵苍凉如许，不碍名园。","胜乌衣门第，瓦砾对斜曛。","好湖山、从谁管领，耐幽閒、泉石自清妍。","颓阑外，抹倪迂画，一角荒寒。"]},{"t":"疏影 议瞻园雁来红词，悽然动念，依声和之","f":"古风","c":["湘江坠月。","有塞鸿唳秋，云外凄咽。","倩女离魂，灵幻霜根，啼鹃泪点殷血。","珊瑚绛树交柯影，舞乱了、霓裳三叠。","误陇头、春到缃梅，寄远玉葱亲折。","不恨胭脂见妒，御沟正叶落，红恨波缬。","木笔过廊，锦字斜书，怨写西风一瞥。","东家漫学芙蓉醉，潮晕影、艳痕生颊。","喜近依、黄菊东篱，点缀晚香时节。"]},{"t":"少年游 游兴减尽，清明闭门，是又一境也","f":"古风","c":["去年心事愿春知。","消息问桃枝。","十里龙华，游人多处，故勒玉骢迟。","而今怕见春光老，心事付支颐。","鶗鴂声中，消魂更在，百草歇芳菲。"]},{"t":"兰陵王 寄怀许少白蓟门，依清真四声","f":"古风","c":["斗杓直。","斜倚长空荡碧。","燕台树、春信几番，隔岭梅花暗无色。","貂裘敝去国。","忘识。","东华旧客。","桑沧恨、追话旧游，珍托云鸿去书尺。","蛮江记萍迹。","正鸟寄回樯，鸥笑争席。","饥驱何补泉明食。","剩压袖诗重，伴装琴古，归帆风利破数驿。","怅人阻南北。","悽恻。","怨怀积。","耐烛影秋寒，花事春寂。","烟波渺渺苍无极。","况触恨杯酒，閟音亭笛。","西崦曾翠，剪赠我，晕砚滴。"]},{"t":"念奴娇","f":"古风","c":["杨花遗恨，怅芳丛魄冷，素馨薰月。","黄土佳人今古恨，天护埋香荒碣。","白马朝来，彩云暮散，蜀道啼鹃血。","当是宫女，料应幽恨能说。","锦江流水年年，飞红一片，付与辞春鴂。","洛浦翩鸿神女赋，写出陈思呜咽。","薄命凋花，柔情黏絮，黄绢人称绝。","清凉坏壁，近传佛赞苔啮。"]},{"t":"三株媚·辛未清明","f":"古风","c":["鸪声烟雨里。","又春城花飞，乱撩心事。","渠爱南翔，问此时何苦，阻人归计。","闭户微吟，情悄悄、帘阴委地。","桃讯龙华，都付游鞭，随车拾翠。","邱陇松楸捐弃。","怅憔悴天涯，十年游子。","绣地鹃红，问几番寒食，佳城空闭。","屈指春闺，凭慰问、家山薜荔。","影入关河归路，残灯坠穗。"]},{"t":"三株媚·登舟山谒成仁祠","f":"古风","c":["渔樵閒话里。","道撄城援桴，鼓声先死。","水国山围，算沈沈层壑，藏舟无地。","一域同归，碧血绣、苔花浓紫。","宫井凄凉，落叶谁题，涎蜗成字。","犹识臣心如水。","剩满地梨花，闭门亭倚。","力谢回天，看浅清瀛海，顿时尘起。","日落云颓，堪指点、旌旗残垒。","今问江山何似，英魂识未。"]},{"t":"汉宫春 为人题蓟门秋柳图","f":"古风","c":["春去多时，换金堤旧影，风媚烟姝。","低徊阅人倦眼，残梦模糊。","灵和咫尺，问前尘、天路今殊。","空剩取、长条管领，盘雕跃马平芜。","沈醉软红梦醒，斗舞腰歌扇，解妒欢娱。","西风玉关夜度，尘暗铜铺。","宫鸦背冷，比台城、残照何如。","眠起事、东君觑惯，等閒芳槛休扶。"]},{"t":"庆春宫","f":"古风","c":["陡壁奔雷，长波逝电，坠潭烟雾冥濛。","跳白珠尘，界青练影，蜿蜒穿破蒙茸。","闻根何事，顿疑是、昆阳雨风。","生绡百丈，离合神光，残墨云龙。","是何变幻天公。","神女晨妆，黛远烟浓。","破碎袈裟，庄严璎珞，丝丝掩映玲珑。","归源千派，专一壑、休休有容。","在山小住，免助人间，波浪重重。"]},{"t":"渡江云 为陈柱翁题黄宾虹桂林山水长卷","f":"古风","c":["飞仙苍玉佩，御风散落，疏密点漓江。","剑从天外倚，剖璧分圭，千里近相望。","沧波残画，仗秋阳、点缀丹黄。","怀旧游、吸光餐渌，诗思乱蓬窗。","谁降。","年华晼晚，心迹依违，算湘累天放。","空坐阅、云涯芳杜，劫海红桑。","羁愁剪断淞江水，梦故山、林桂丛荒。","图展对，怡然一叶徜徉。"]},{"t":"风入松 赴普陀，舟过舟山，望旧居作","f":"古风","c":["仙风著意引舟迟。","辽鹤偶然归。","巢痕指点云深处，又何堪、烟雾迷离。","劳燕东西靡定，鸡虫得失谁知。","征衫赢得客尘缁。","难染鬓霜丝。","海天空阔人间世，羡山梁、饮啄知时。","江上苍烟不管，白鸥何事相疑。"]},{"t":"虞美人 为了了禅师题古木寒鸦图","f":"古风","c":["山空木谷宜禅定。","幽梦娱清磬。","莫嫌身世隔红尘。","从此鸣声无事惹人嗔。","天怜予尾翛翛苦。","许与枝枝处。","免教飞傍上林烟。","见说琼楼风露有新寒。"]},{"t":"安公子","f":"古风","c":["眼底江湖暮。","那边宜著渔竿处。","一角孤山香海雪，算梅花堪语。","地僻左、狂澜不到鸣榔浦。","莺比邻、近接青青树。","拥夕阳丘壑，亭长头衔新署。","此意凭谁诉。","拍阑生怕惊鸥鹭。","似鲫西台游眺客，几曾逢皋羽。","事到此、菟裘息壤臣归路。","莫浪吟、惹起鱼龙舞。","谢西子多情，倩云又留人住。"]},{"t":"被花恼","f":"古风","c":["春慵燕懒户庭閒，把卷自娱昏晓。","湖海归来壮怀少。","钻书蠹癖，抱香蝶梦，一枕蘧蘧觉。","摩老眼，读从头，余明犹恋桑榆照。","帘外古寒多，谁管飞红落萦草。","纱窗绿涩，铁砚丹枯，问字人稀到。","算年来、百感涌如潮。","怕书客、庞眉被霜恼。","井叶落，似报镫前人又老。"]},{"t":"踏莎行 题谢榆孙溪山读书图","f":"古风","c":["大好溪山，纷来窗户。","书声时逐溪声去。","江南黄叶是何村，行云偏识壶公处。","游屐耕烟，吟灯晕雨。","渔歌层入蘋洲谱。","麻衣草履建阳装，翠微指点吾归路。"]},{"t":"安公子 为吴湖帆题文待诏长门望幸图","f":"古风","c":["幸草青如许。","长门春去谁为主。","兽啮金环推月出，冷闭梨花雨。","望昭阳、笙歌镫火宵连曙。","山海誓、输与长生语。","惜阿娇金屋，终隔回心院宇。","十载承恩处。","垂杨惯惹羊车驻。","胏附荆枝摧折甚，算倚帘人妒。","曾几日、铜铺玉戺空朝暮。","故剑求、传说终无据。","叹城南桐柏，何异郎官坏土。"]},{"t":"向湖边 题林畏庐先生西汉图卷，卷藏秋雪庵","f":"古风","c":["翠拥千屏，红拖双桨，依约晚荷深处。","寄迹西湖，惯扁舟容与。","甚年年、听磬虚坛，观潮荒岸，未逐流花寻渡。","指顾云峦，忽峥嵘绢素。","十里芦霜，白覆词仙宇。","知柳眼看尽，几风流张绪。","语燕歌莺，谱当年金缕。","况逋仙、仙去从朝暮。","丹青笔，留镇寺门清客暑。","唤起吟魂，听斋厨钟鼓。"]},{"t":"洞仙歌 用梦窗体","f":"古风","c":["雨瓢倾了，蚁垤摧秋潦。","泛芥堂坳舞舟棹。","任窃香蜂蝶，越迤逦东墙，狂恣纵、邃慢深帏穿到。","痴烟方困柳，梦惊回、拟倩阑扶望终渺。","燕参差、莺懵懂，量暖评寒，回屐路、人报飞红千绕。","护花计、关心问西园，自整金铃，系绳须早。"]},{"t":"洞仙歌·忆梅，辛未十二月十四日夜坐作，用屯田体","f":"古风","c":["五月狂飙卷。","江城地、梦破笙歌庭院。","况邮亭门闭，蹇驴人倦。","溪流涨、村桥中断。","禁苑树、珍巢从鹤恋。","春欲半。","奈绿萼臞仙，信渺罗浮雁。","一旦冲寒恰恰，破腊匆匆，借得东风，荡开寂寞蛮春，蓦地翠禽喧暖。","巡檐不入高人眼。","纵牧竖、初花摧折遍。","思寄远。","问签程、水驿山邮路千万。","渐散乱。","又忍事催琼琯。","残英飞尽，诘朝尊俎嗟来晚。"]},{"t":"安公子 烛泪，和蛰云","f":"古风","c":["翠冷烟凝紫。","华堂送客添愁思。","玉指金环勤拂拭，泻调脂铅水。","说旧事、凄凉背拥樊通髻。","膏自煎、总为凡心缀。","问伤秋尚别，到底汍澜谁替。","别有繁华地。","欢呼博簺花丛里。","粉腻香薰缨半绝，臣髡微醉甚。","依旧鲛人，珠颗缤纷坠。","怕到头、兴尽还垂涕。","况红湿鸳衾，对泣欲怜无计。"]},{"t":"瑞鹤仙 挽彊村师","f":"古风","c":["蘋洲沈短日。","望素云黄鹤，辽天无极。","思悲顿寥寂。","剩锦笺凄调，玉棺铭笔。","吟边易篑。","老臣心、词人一席。","痛百年垂死，中兴病枕，几番寻觅。","曩昔。","云瑶校曲，桐荫题图，倏成陈迹。","翠微峭壁，傍船指空沈碧。","抚遗编依黯，高歌不忍，泪落江南怨笛。","又伤心、汐社春芜，盟沤无色。"]},{"t":"减字木兰花","f":"古风","c":["江南骏骨。","埋没金台尘土窟。","侧耳铜丝。","疑是成连海上时。","寻消问息。","一旦相逢如故识。","文字因缘。","犹赖登场傀儡牵。"]},{"t":"芳草渡 依清真四声和伯越还乡之作","f":"古风","c":["息故里。","怅倦鹤归来，暮天无侣。","乍觅巢痕梦，飘摇又委风雨。","为旅情味苦。","思园莺能诉。","谢送我、夜半潮生，一棹归去。","回顾。","岭云望远，草绿清明墦祭路。","漫虚拟、支茅傍冢，墟烟凝窗户。","松楸抚遍，乱撩起、絮泥閒绪。","但注目，似蝶钱灰倦舞。"]},{"t":"锦帐春 吴淞和约成后作，用稼轩体","f":"古风","c":["动地惊雷，欺花骤雨。","正春困、鹧鸪庭户。","霎时晴，残醉醒，又燕莺歌舞。","有谁知苦。","送客尊罍，割鲜刀俎。","敲梦断、邻家砧杵。","楚江皋，神女佩，抵阳关旧谱。","有人堪语。"]},{"t":"大酺 香江登高","f":"古风","c":["正岛帆寒，窗檠短、憔悴天涯羁客。","亭皋凋木叶，怕东篱秋瘦，照人无色。","泛绿萸尊，蹴红绳屐，芳草还堪眠藉。","迷离西崦路，算斜阳虽好，乱云重幂。","况催近黄昏，霎时风雨，满城沈寂。","中原劳目极。","星星火、一望平原赤。","况又是、齐乌争幕，辽鹤迷归翅。","低垂空留残翮。","那怪高飞雁，烟水阔、远怀沙碛。","奈圆月，非今夕。","苍霭环合，山下归途如漆。","迟明问谁耐得。"]},{"t":"石州慢 新雁","f":"古风","c":["万籁齐喑，寒碧一灯，人醒高阁。","云端缥缈边声，偶被朔风吹落。","传来消息，惹起种种新愁，人民休问辽东鹤。","赢得入关情，受征夫珍托。","遥度。","连台烽火，裂地冰霜，爪痕难著。","遑计榆边，万里汉家城郭。","重衾梦恋，任汝叫遍南楼，回书情谊闺人薄。","唱入破家山，正柳边风恶。"]},{"t":"后庭宴 题崔白月高斋行钵图","f":"古风","c":["老我毡青，磨人墨黑。","映来衰鬓无情白。","打包行脚倚朱门，饥驱聊乞泉明食。","主人有意听歌，爱汝歌声金石。","先生酒食，算异残羹炙。","莫道砚田安，来年非暖席。"]},{"t":"石州慢 夏吷老以词集见贻，并索题其填词图，依韵代柬","f":"古风","c":["如此江山，人世几逢，风月清白。","况教天赋多材，杯里光阴能惜。","红桑看老，钓竿归拂珊瑚，鸿冥烟水迷踪迹。","剑吷起龙吟，动寒芒星织。","幽寂。","生涯何似，画笔丹香，书声金石。","眉阁晨昏，相对裁红锤碧。","霜歌缥缈，飞来千里关山，阳春入弄梅花笛。","梁月正俳佪，有羁人相忆。"]},{"t":"天香 自题抱香室填词图","f":"古风","c":["毛谢飙扶，肠凭酒涤，蹉跎身世如此。","汐社随沤，吴云泊雁，结习未忘语绮。","西窗嚼韵，惊梦里、睡夜龙起。","孤悄吟灯支影，寂寞添香纤指。","词仙御风万里。","马塍花、落残红紫。","指点翠微高处，自今休矣。","抱得含香足未。","图不出、危弦变声徵。","漫道丹青，痕痕是泪。"]},{"t":"一萼红 和白石","f":"古风","c":["古藤阴。","梦黄农上古，短发谢华簪。","云雁书愁，霜蛩咽冷，灯烬还觉烟沈。","才唱得、秋词入拍，又磅礴、羲帖仿来禽。","榆景催人，花楼伤客，时怯登临。","电泡吾生如寄，况鸡虫得失，何足关心。","无味咸酸，垂残筵席，莫非忧患相寻。","向平愿、楹书枉托，更何取、遗子满籯金。","借问蓬莱，几程几许云深。"]},{"t":"临江仙 题谷雏吴楚越纪游画册","f":"古风","c":["波眼山眉烟媚，吴头楚尾春浓。","霜花枫叶客程中。","归来双袖重，粉本半残丛。","岭北经描半壁，辽东尚有诸峰。","白山黑水阻游筇。","他年修剩稿，莫忘旧螺谷。"]},{"t":"减字木兰花 题关颖人司长鱼山枕雨图","f":"古风","c":["姮娥夙约。","今宵底事迟梳掠。","岂为伤离。","泪雨纷纷洒路歧。","催诗有分。","禅榻推敲愁未稳。","止可随缘。","莫笑催妆负客篇。"]},{"t":"满江红 题屈翁山先生寿诗墨迹，为李子云省长作","f":"古风","c":["粤峤山川，试屈指、古今豪杰。","数不到、南园十子，后先蛩蟨。","岭表三家成对峙，江南一调资提挈。","剩蒲泉、古月照残碑，栖灵穴。","吟龙剑，霜威折。","屠狗辈，风流灭。","望西台云暗，涕痕空雪。","公愤永沈精卫石，私恩一报冈陵帖。","到而今、正气郁行间，神虬结。"]},{"t":"塞垣春 某君不得志于时，有远引意，词以坚之。用梦窗体","f":"古风","c":["如梦花风荡。","寂寂送春门巷。","鸥閒水戏，龙眠秋静，天地夷旷。","看潮痕、旦暮分消长。","代谢事，盈虚状。","鲁阳戈，娲皇石，古今人事无两。","休笑漆园狂，也知羡渊鱼，临濮濠上。","人海浪如山，勿轻弄双桨。","笑无知鹬蚌。","方向东君，乞阴晴，已投网。","黄犬上东路，输与青山往。"]},{"t":"百尺楼 题彭立本先生竹石图。彭为岭南明末节士","f":"古风","c":["石烂海先枯，竹劲风能折。","何物生来性最坚，心史层函铁。","不转任江流，有点皆湘血。","写出殷薇汉腊心，磊落遗民节。"]},{"t":"上林春 山行宿樵家","f":"古风","c":["云海苍茫前路。","烟语隔、薜萝双户。","主人鸡黍多情，似劝我、息劳小住。","寻春枉事蜡屐去。","芳草径、是春来处。","尘心流水同閒，准备听、疏钟零杵。"]},{"t":"菩萨蛮 读温飞卿词，恍惚有悟入处，急走笔效之","f":"古风","c":["送君方梦巫山峡。","荒村残柝惊魂怯。","门外月如霜。","辘轳泉水香。","偎人犹絮絮。","执手翻无语。","寒意破鸡声。","长亭还短亭。"]},{"t":"菩萨蛮","f":"古风","c":["沈郎腰为耽吟瘦。","况当惜别殷勤后。","珍重劝加餐。","关山行路难。","笋将程十里。","熨帖心如许。","霜滑马蹄迟。","随郎郎不知。"]},{"t":"菩萨蛮","f":"古风","c":["十年薄倖漂流惯。","荼薇望断楼头眼。","牵系到郎心。","征尘思浣襟。","梦归枫叶黑。","咫尺屏山隔。","鹦鹉傍前棂。","呼人人不应。"]},{"t":"菩萨蛮","f":"古风","c":["蝶蜂有意寻芳去。","好花无奈经风雨。","春色怨来迟。","落红今更稀。","问花花不语。","谁识芳心苦。","零落惜余香。","行人空断肠。"]},{"t":"菩萨蛮","f":"古风","c":["新篁移得筼筜种。","亭亭碧玉阶前耸。","吟就付琅玕。","枝柔不任镌。","舞风兼浴露。","原恃春阴护。","自有凤凰栖。","野烟时复迷。"]},{"t":"菩萨蛮","f":"古风","c":["枝头春色非常在。","醉人花气空如海。","金井起秋风。","梦醒惊落红。","落红还不扫。","知惜韶光好。","胡蝶过墙来。","玉阶生绿苔。"]},{"t":"菩萨蛮","f":"古风","c":["园林日日风和雨。","采花酿蜜蜂儿苦。","蛛网漫天横。","尤防新放晴。","无多香可窃。","难补巢痕裂。","辛苦为谁尝。","堪人评短长。"]},{"t":"菩萨蛮","f":"古风","c":["苍黄踯躅无人径。","垂垂况迫崦嵫景。","林外一声钟。","涧花迷路红。","翠微还在望。","努力拿云上。","语语碧栖遥。","有人飘袖招。"]},{"t":"菩萨蛮","f":"古风","c":["铁衾寒入愁时节。","老来心事凭谁说。","不恶是鸡声。","凭他酣梦惊。","非因看剑起。","烧却萧娘字。","帘外老东风。","邻家无数红。"]},{"t":"菩萨蛮","f":"古风","c":["黄河日夜东流去。","除非到海流方住。","住亦未曾休。","鱼龙掀浪愁。","何如潭水碧。","潭上无人迹。","珍重在山清。","消磨出世情。"]},{"t":"菩萨蛮","f":"古风","c":["牛腰学弄无腔笛。","被人呼作吹箫客。","天上渺霓裳。","众仙歌舞忙。","碎琴中散忍。","斫柱湘东愤。","何事又沈吟。","晓风残月心。"]},{"t":"菩萨蛮","f":"古风","c":["从前曾嫁金龟婿。","齿痕恩爱红留臂。","呼婢买胭脂。","旋歌弃妇词。","繁华非我福。","生性贪幽独。","弥勒许同龛。","春风休卷帘。"]},{"t":"菩萨蛮","f":"古风","c":["绿华一谪人间世。","时妆学得抛家髻。","厨下作羹呼。","回头顾小姑。","鞦韆辞夙约。","恩怨防邻觉。","青鸟莫窥人。","梨花深闭门。"]},{"t":"菩萨蛮","f":"古风","c":["毡毹舞罢思休歇。","偶拈裙带翻成结。","莫唱想夫怜。","偷将眉恨传。","百思无好计。","枉费天涯泪。","相约语餐霞。","痴心思报他。"]},{"t":"莺啼序 和梦窗","f":"古风","c":["春老洞深寒在，倩痴云守户。","喜檐鹊、取次呼晴，又报鼍鼓催暮。","卸樯燕、寻巢倦睇，青青总是他乡树。","算红情销尽，终输雨余泥絮。","年少灯檠，傍壁夜泣，没墟烟嶂雾。","溯红渐、溪入清佳，放歌初写纨素。","计中秋、千山桂落，听宫莺、缘悭金缕。","被天风、吹坠江湖，课閒拳鹭。","东华车马，古署林鸦，十年半逆旅。","漓水阔、误他湘雁，楚佩轻委，瘁羽孤单，怎禁蛮雨。","虞姬妒恨，莫愁痴视，渔灯不暖韩江梦，舣扁舟、芦岸呼人渡。","樱花问讯，葡萄买醉，归来卜居，那是吾土。","头颅尚在，偃蹇山林，欠漆园栗苎。","拟料理、襟痕袖稿，百感苍茫，鬓怯霜欺，烛危风舞。","回峰自警，余粮休恋，脱笼飞作蓬岛客，漫思归、危立辽东柱。","关心俗状尘容，浪迹云山，鹤猿讶否。"]},{"t":"莺啼序·咏史，和梦窗赋荷韵","f":"古风","c":["东沟旧愁未洗，又桑乾咽水。","北鸿到、问讯寒梅，著枝多少新蕊。","见说半空飞霹雳，儿童笑指天花坠。","任胡尘貂锦，归魂不入闺思。","初讯东风，撼户动幕，苦抛家浪子。","劳远望、签盼归程，雁来人总不至。","弃珠崖、画分玉斧，连环解、方劳葱指。","奈天骄、沙漠跳梁，又生他意。","愔愔巷陌，醉舞酣歌，恼春人梦寐。","驱虎豹、昆阳夜吼，震荡风雨，鼓死凭壕，防分划地，枕戈饮泪。","量沙夜唱，涸鱼空望，西江润赋，流离琐尾悲逋瘁。","腥潮怒吼，重重摧折藩篱，涨到武陵源里。","兴亡有责，鲁国孤嫠，也抛红怨翠。","今又报、燕云肩背，俯瞰秦城，饮马泉乾，宿乌宵起。","渔阳鼙鼓，霓裳惊破，吴山高处人立马，恐长江、天堑终难恃。","伤心木客，秋吟当哭，长歌泪盈茧纸。"]},{"t":"八声甘州","f":"古风","c":["喜青山、尚许客重来，禽猿话前尘。","悔天涯书剑，约抛钗誓，泪凝襟痕。","初试咸酸况味，鲁酒冻胶唇。","收拾残灯事，商略黄昏。","蛮海漂流孤燕，逐估樯南北，遑觅芳邻。","有相怜华发，烟岫蹙螺颦。","算东风、园林妆点，问落花、流水几何春。","还栖影，爇心香处，先断知闻。"]},{"t":"绕佛阁","f":"古风","c":["冻禽戢影，阑雪澹糁，花落人悄。","偎影屏小。","去途曲折，相烦短檠照。","雁来新杳。","江上问讯，明日潮早。","缄恨多少。","晓来起拾，残英粲盈抱。","密意付钗卜，带解蟢飞羞向道。","还记燕梁，双栖亲语笑。","叹两地相思，花与春老。","路长波渺。","正出没关山，空想乌帽。","梦归迟，寺钟撞晓。"]},{"t":"浣溪沙 普陀化雨学校前观海，得海水忘机潮撼岸七字。归后足成此调，即以题校长宽融师题名册","f":"七言古诗","c":["佛狗生来性本同。","缁衣无那染尘红。","惊人赖有一声钟。","海水忘机潮撼岸，虚空无滓夜生风。","沈吟羲易警悾憧。"]},{"t":"西江月","f":"古风","c":["流水落花天地，鸢飞鱼跃襟怀。","此身死处便堪埋。","我是乐天一派。","转劫生防地狱。","皈宗愿向天台。","归途大抵即来途。","绝妙连环都解。"]},{"t":"陌上花 读彊村三集，和张翥韵","f":"古风","c":["藤阴满地，东风刚报，马塍春晚。","痛绝西州，何处昔年门馆。","蜕蝉剩有辞秋语，一读一回肠断。","鹧鸪声、病室维摩，泪随花散。","署词人誓墓，臣心暗苦，冷似枯桐空半。","雨晦泉寒，谁信暮烟能暖。","剧怜海角红光现，不照夜台落雁。","正微吟、草长江南，犹是燕慵莺懒。"]},{"t":"踏青游","f":"古风","c":["恨袅晴丝，商量试寒深浅。","鵊鹎唤、韶华又晚。","数番风，信倦我，探芳心眼。","问客路、长亭短亭烟柳，自古送人何限。","故国清明，饧箫几回喧暖。","算等是、钱灰酒盏。","认松楸，非旧树，梦痕疑幻。","凝望处、伤心几人知我，莫问南天归雁。"]},{"t":"扬州慢 癸酉清明后一日作，依白石韵","f":"古风","c":["残暝煎愁，嫩寒阁梦，绕屏静数归程。","问天涯那处，是柳眼长青。","望红满、甘泉猎火，送春梅雨，难洗蚩兵。","痛孤飞、南雁惊弓，魂堕秦城。","古原野烧，正伤心、宿草难青。","况鞭石神遥，搴芳客早，那不关情。","几许落花消息，东风紧、燕雀无声。","纵罗衾重恋，秋来依旧愁生。"]},{"t":"梁州令","f":"古风","c":["老箨何年解。","认汝风霜能耐。","那须涤面洗心时，自饶佛眼慈眉态。","年来腰力登楼惫。","汝责无旁贷。","从今行脚万千山，叮咛步步垂青待。"]},{"t":"好事近 春暮种桐于普陀古塔侧，喜有生意","f":"古风","c":["数尽落花风，绿意沈沈寒勒。","移得乳桐双树，露生机端的。","知稀何贵养琴材，弹开海天碧。","要把年年秋信，报山僧知得。"]},{"t":"疏影 和李孟符柳","f":"古风","c":["搓黄揉碧。","为惜春伴侣，牵挽春色。","老去金城，暮合隋堤，几树归乌梭织。","风流张绪当年事，顿暗老、江南羁客。","拜绪风、彭泽柴桑，健试近来腰力。","眠起颦眉暗里，对人辄起舞，防露心迹。","金缕翻衣，丝绦簪髻，作意尊前欹侧。","知他悟到沾泥絮，应不许、翠楼相忆。","况陌头、攀折游鞭，久绝章台消息。"]},{"t":"浪淘沙慢 四月二十夜雨中","f":"古风","c":["峭寒里、魂苏露筱，甲勒烟蒻。","灯檠余烬乍落。","饧箫滞响又阁。","似见说、东风来势恶。","算新燕、乖巧先觉。","任坠红、西园厚成寸，閒墙碎苔啄。","依约。","个人熨眉萼。","看破碎、江南残春稿，粉黛都黯却。","更絮舞回飙，网坠纤络。","蜂欺蝶虐。","到晴明、空剩凄清铃索。","宵警须宽韩卢缚。","阑干拍、禁喧斗雀。","众香国、蒿莱参杜若。","再收拾、冷落林亭，护幔幕、何堪再悔今番错。"]},{"t":"诉衷情 观海","f":"古风","c":["灵胥白马拥涛来。","荡绝地天开。","蛟龙何事余怒，入壑吼春雷。","花四溅，白皑皑。","撼前崖。","射潮弓弱，溯汉槎遥，人隔蓬莱。"]},{"t":"隔浦莲近","f":"古风","c":["天涯游子去久。","帘底腰肢瘦。","多少红楼道，青骢系、谁家柳。","添得怀僝僽。","归鸿远、枉把回文绣。","抱愁候。","郎归两字，门前忽报鹦鹉。","饯春薇约，今日思量相守。","陌路萧娘轻去就。","依旧。","坠欢重拾人后。"]},{"t":"摸鱼子","f":"古风","c":["一痕痕、积沙吞岸，潮来犹是添涨。","鲁个难返西崦景，空负恋红帘桁。","山月上。","抚对影、头颅依旧风尘状。","乾坤浩荡。","拟棋局光阴，蘋花心事，并入五湖桨。","从来错，塞海排山冥想。","邓林中道捐杖。","焦头烂额终何补，赢得狂名强项。","君莫忘。","斫地王郎，几个留天壤。","魑魅魍魉。","算禹鼎图形，山经写貌，千古耿尘坱。"]},{"t":"念奴娇 落叶，追和冯君木","f":"古风","c":["洞庭波阔，问悲秋宋玉，赋情何许。","见说红衣南岸客，坐受西风老去。","残画沧洲，余程水驿，头尾连吴楚。","林疏露出，瘦山江上无数。","时节烟景江南，阴阴浓绿，指点春归路。","一碧无情千树冷，今剩昏鸦尔汝。","客梦灯残，蛩声笛冷，又咽重阳雨。","宫沟何处，题红枉费情语。"]},{"t":"瑞龙吟 山中饯春，和清真韵","f":"古风","c":["天涯路。","年年坠劫风花，罥愁烟树。","行人赶上江南，荒村绮陌，寻他甚处。","枉延伫。","陡忆上林春满，建章门户。","五陵骄马嘶风，招展花枝，枝枝解语。","转瞬东风老大，江南草长，群云歌舞。","无那令人销魂，痕烧非故。","断肠婪尾，都是方回句。","空相忆、藤阴买醉，蘅皋延步。","魂逐潮来去。","丝杨不续，尘缘断绪。","理罢愁千缕。","衣不著、纷纷诸天红雨。","山深莺老，旧情休絮。"]},{"t":"醉桃源","f":"古风","c":["当窗钻纸笑蝇痴。","旁观明是非。","眼前红绿总迷离。","彷徨悲路歧。","风烛短，局棋危。","邻鸡破梦啼。","桑榆尚有几斜晖。","水流今向西。"]},{"t":"齐天乐 偕夏臞翁登市楼下瞰","f":"古风","c":["黄沙白骨秦城路，谁驱五丁移此。","断壁蓬支，空椽藓绣，王谢依稀邻里。","斜阳半紫。","犹凄恋当年，汉旌遗垒。","歌舞繁华，漂花春去付流水。","何堪重问往事。","裹创犹肉薄，弮刃东指。","捧土填川，挥戈返日，空使英雄垂涕。","笙箫残市。","有倦客凭阑，壶觞无味。","逃酒逃禅，问谁知我意。"]},{"t":"桃源忆故人 非园小睡","f":"古风","c":["天涯那得真閒处。","花外竹篱茅户。","消得江南残暑。","梦绕青青树。","何须邻笛将愁诉。","惹得旧愁千缕。","危石留云和月住。","应有秋魂语。"]},{"t":"满江红 平调，题吕女士碧城集","f":"古风","c":["谪下双成，尽游戏、鸿濛八荒。","铅华洗、簪笄生色，剑佩行装。","荆树风霜经寂寞，木兰红紫讵寻常。","著先鞭、素手指山川，怀渺茫。","蛮语会，杂冠裳。","漱玉集，调笙簧。","掇十洲花草，都入奚囊。","豪侈气饶蔬笋味，聪明魄濯雪冰凉。","愿钗裙、翘首碧城霞，心瓣香。"]},{"t":"惜秋华 和梦窗韵","f":"古风","c":["萧飒寒声，撼窗棂、似叩羁栖愁抱。","门掩灯孤，相怜尚垂青照。","尘劳不许心閒，猿马走、憧憧尘扰。","绮语问谁呵，顾影自欹吟帽。","篱菊报秋老。","算斜阳木末，余明犹好。","蓬路远，残翮短，任教迟到。","须知宇宙原宽，泛沧溟、江湖杯小。","知了。","软红尘、误人多少。"]},{"t":"金缕曲 赠梁海滨先生","f":"古风","c":["天坼飞仙死。","问何人、羽衣腰剑，凭高凝睇。","国史儒林文苑传，竟是蓬瀛谱记。","莫疑是、长安裘敝。","照座须眉真苍古，目棱棱、岩电光腾紫。","跨燕越，犹尺咫。","尘寰有意閒游戏。","战场花、摘从北口，又来南市。","海水天风相鼓荡，想见雄心万里。","奈宇宙、满空渣滓。","安得如公千万辈，使蛟虬、认识干将利。","公是我，赤松子。"]},{"t":"谒金门","f":"古风","c":["休认错。","蜃气空濛楼阁。","十九耕耘无一穫。","有情仍纸薄。","无力絮花漂泊。","管甚坠茵黏幕。","偶傍鞦韆红锦索。","也须防燕觉。"]},{"t":"谒金门","f":"古风","c":["金粉地。","暖日好风罗绮。","装出城中高尺髻。","路厖惊远避。","草妒游裙摇翠。","烛替愁人垂泪。","纵有相思无限字。","茫茫何处寄。"]},{"t":"凤栖梧 读中州乐府，李扶风别有溪山容杖履，等閒不许人知处之语，因广其意","f":"古风","c":["大隐市朝终我误。","除却山林，难觅安心处。","随意经行随意住。","渔樵非是閒俦侣。","拟买沃洲充隐去。","纵许人知，知也谁寻汝。","夜里波涛风里树。","跫然空谷山灵语。"]},{"t":"阮郎归 红白桃花","f":"古风","c":["铅妆初罢点唇脂。","蓬门人面窥。","刘郎重到眼迷离。","烟霞交路霏。","玫瑰笑，雪霜姿。","东风生是非。","武陵渔父纵相思。","知他心向谁。"]},{"t":"虞美人 普陀慧济寺铜水瓢柄上现大士像","f":"古风","c":["杨枝甘露随瓢注。","镜不烦铜铸。","圆通宝相看分明。","犹恨烟云叆叇掩冠缨。","现身说法楞严记。","蛤蜊庄严示。","此中见佛此中寻。","莫谓眼缘观外未聆音。"]},{"t":"散天花","f":"古风","c":["栴檀香老忽春生。","维摩花雨散，著身轻。","无根芝草恋珠缨。","芙蓉亲手把，去朝京。","斗印何须挂肘肱。","搴芳三秀挹，玉亭亭。","神仙洞府暮云青。","天台千古月，伴琼英。"]},{"t":"虞美人","f":"古风","c":["生怪无风还作浪。","海阔龙吟壮。","花漂春去未干休。","试问古今淘尽几多愁。","胥涛倾入羁人枕。","拥被新寒噤。","潮声朝夕几曾停。","听自尘心净处更分明。"]},{"t":"西河 长城怀古，和清真","f":"古风","c":["形势地。","秦关百二雄峙。","燕头晋腹尾皋兰，龙蛇陆起。","窥边猎火燎平原，黄沙红入无际。","饮马窟，罴冢是。","安危钧发悬系。","旌旆影靡鼓声沈，坏云崩垒。","障亭落叶扫秋风，夜潮呜咽渝水。","马茶见说久互市。","甚渝盟、一蹴千里。","锁钥丸泥何世。","怅关门、牝铁宵飞，空说鞭石移山，渔歌里。"]},{"t":"秋思·聊社集非园时来索和。忆数年前曾一度集此，园主令弟甓生预焉，今已矣。酬以此解，不胜今昔之感","f":"古风","c":["湖海伤春客。","正沃洲深处，闭门岑寂。","孤影荡愁，旧欢寻梦，花雨檐滴。","记觞兴诗情，呕肝战拇誓破敌。","少壮怀，今顿息。","念绝句旗亭，俊游金谷，怎奈奋飞无分，身悭双翼。","悲极。","黄垆久寂。","况隔墙、哽咽哀笛。","酒残沾地，西堂惊起，醉魂此夕。","料洛艳、迟迟正开，风日悽断甓。","汐社事，悴憔色。","试检点尊前，高阳多少发白。","许把阑干暗拍。"]},{"t":"江神子 落伽山","f":"古风","c":["鲛宫波暖颔珠浮。","戏潜虬。","玉壶秋。","一碧莲花，洋里水如油。","时有蒲帆环槛过，斜照里，过渔舟。","山灵何必赋高邱。","短姑头。","隔龙湫。","有客翠微，听磬事寻幽。","顷刻仙风双桨送，杯渡也，稳于沤。"]},{"t":"法曲献仙音","f":"古风","c":["身世雕龙，命宫磨蝎，萧瑟江关词赋。","没字腔哦，有涯生遣，旁人怎知心苦。","果唱到，阳春曲。","谁与和金缕。","酒徒墓。","署词人、一坯埋碧，心史稿，休认等閒绮语。","哀乐纵无端，付琵琶、幽怨能诉。","法曲霓裳，大罗仙、天上箫谱。","异花间侧艳，止拾十洲零羽。"]},{"t":"祝英台近 题姚景翁天醉楼填词图","f":"古风","c":["海桑红，宫黍秀，年冷鹤能语。","满地江湖，寒暖变晴雨。","有人抱膝长吟，茶烟禅榻，老不管、莺花朝暮。","潮分付。","往来送尽兴亡，湘累为谁苦。","醉醒无端，写尽问天句。","似闻人海浮沈，江关萧瑟，称为我、駏蛩俦侣。"]},{"t":"澡兰香 癸酉闰重午","f":"古风","c":["钟馗守户，罗刹跳梁，说甚锦袍绛帻。","残痕臂缕，余滴蒲觞，续命荡愁无力。","算龙艭、千桨齐飞，难招沈沈楚魄。","浩渺潇湘潭水，空摇烟碧。","况复横汾一曲，戏水嬉停，分波界画。","舟移剑徙，鼓死旆收，两岸阵云先墨。","羡红榴、巧衬茜裙，长袖终嫌地窄。","恐搅乱、镜影波心，晴川风色。"]},{"t":"宴清都 题高潜翁寒灯课读图","f":"古风","c":["我亦单寒子。","蓬门夜、母儿形影相倚。","秋机织泪，春灯熨梦，烟残坠穗。","瓻书借向东邻，便绕膝、殷勤问字。","诵琅琅、建水高瓴，寒宵过午忘寐。","生前无分鸡豚，墓门寒食，望风悬泪。","珍图手展，丸熊画荻，俨然前事。","帘前雾重成滴，摇壁影、葳蕤细蕊。","陟屺吟、能否招魂，涕零茧纸。"]},{"t":"西子妆 端午夕对月，和蕙石","f":"古风","c":["孤影伴愁，短歌送节，举目天涯愁满。","秦关尘涨楚江昏，吊湘累、芷兰哀怨。","归帆似箭。","更谁管、潮痕暗换。","殢乡关，问晓风残月，凭谁能劝。","连村晚。","浴鹭春波，一水匀寒暖。","时新眉样费商量，话西窗、青灯黄卷。","风尘阅遍。","享家帚、千金同玩。","合我成三，月照琴楼酒盏。"]},{"t":"庆春宫 芭蕉，和蕙石","f":"古风","c":["秋味凄清，春心舒卷，也来急雨阑东。","期雁擎书，调莺欹扇，旅情乡梦都慵。","绿天深处，净碧唾、飞尘谢红。","有时题句，纸贵何妨，喜对珍丛。","弹章竹拜临风，小草晞阳，见蔽阴浓。","凭藉园林，招摇风露，一场迷鹿终空。","雪图摩诘，识身脆、金刚漫同。","积愁成结，邻圃丁香，代惜渠侬。"]},{"t":"惜红衣 和蕙石，并题其小照","f":"古风","c":["壁倚琴囊，杯严酒限，伴人楼月。","得句微哦，閒情自怡悦。","檐花绀滴，惊野火、宵红胡骑。","冬猎。","秦曲鹧鸪，望南云愁绝。","袁门扫雪。","归燕樯连，沧溟稳舟叶。","刘郎又到，白发更堪镊。","赢得故庐无恙，相顾头颅曾说。","问返耕何日，邻壤绣塍鳞接。"]},{"t":"朝中措","f":"古风","c":["叮咛被襆出门时。","日影黯崦嵫。","树古鸦昏吏老，摇红烛映垣薇。","翻阶芍药未成诗。","宫漏出花迟。","年少东华旧梦，空山回首依稀。"]},{"t":"朝中措","f":"古风","c":["关门屏蔽峒回环。","匹马客衣单。","树海秋风作浪，无端飞入琴弦。","丹铅颜色闇橐键。","舞袖碍回旋。","卧榻耽耽虎伺，鵩声啼破苍烟。"]},{"t":"朝中措","f":"古风","c":["荒山瓯北费诗才。","夜静虎巡街。","月底歌声嘹喨，前山并蒂花开。","南天飞雪白皑皑。","冷气迫衙斋。","催我声声归去，杜鹃还被莺猜。"]},{"t":"朝中措","f":"古风","c":["昌黎谪宦岭东陲。","满县袅花枝。","九月秋风垓下，凄凉剑底红飞。","羽书军檄火星驰。","冠虎噬人肥。","孺子沧浪濯足，中流一舸逶迤。"]},{"t":"一斛珠 海珠一役，王广龄厅长、汤觉顿代表死之，徐君勉跳而免。起事者意在徐，而徐反免，有幸不幸存焉","f":"古风","c":["惊雷蛰起。","孽龙腥喷波成紫。","封姨过处花纷坠。","血不登盘，狼藉殷冠履。","鱼服閒游忘上饵。","庭槐风倒魔王喜。","虾蟆胆落争趋避。","今日园林，中有伤心史。"]},{"t":"一斛珠","f":"古风","c":["天然清绝。","断桥残雪平湖月。","淡妆浓抹波光瞥。","加减俱非，色岂人工设。","曲折赤阑连岸接。","凿开混沌胸成穴。","庄严金碧梅花劫。","西子魂归，痛洒春鹃血。"]},{"t":"一斛珠","f":"古风","c":["黄沙漠漠。","穹窿方垒金棺托。","神巫炼骨珍灵药。","地久天长，何事南山椁。","疑冢漳滨终觅著。","茂陵玉椀人间落。","形骸留得终缠缚。","捣麝成尘，何似归寥廓。"]},{"t":"早梅芳近 纪梦","f":"古风","c":["生事抛，偷閒好。","身已蓬莱到。","金银宫阙，灿烂寒花烛龙照。","袖轻云雾重，眼大乾坤小。","忽天鸡试唱，烟裂一声晓。","梦将回，惊未了。","又坠荒山道。","晨钟几杵，客枕孤身在江表。","蠹饥书未化，蝶稿香仍抱。","柰关心，日斜仙路杳。"]},{"t":"上林春慢 癸酉公腊未尽半月作","f":"古风","c":["树老号寒，天黯压檐，欲雪炉空无酒。","贾岛祭诗，梁园授简，工夫料量初就。","腊附待换，怎情绪、乱丝依旧。","不堪闻，是隔苑雨风，酿愁时候。","乍阴晴、几番饤饾。","春消息、待漏陌头烟柳。","夙约比邻，新欢故国，娇心耐人重叩。","踏青伊迩，还等个、寻芳珍偶。","陇云深，数梅驿、一枝来否。"]},{"t":"鹧鸪天","f":"古风","c":["莫遣閒愁一旦消。","凭伊伴度夜迢迢。","是谁扣户风敲竹，莫是回帆岸撼潮。","鸦树悄，鸭香蕉。","那得珍珠慰寂寥。","教箫往事浑如梦，惆怅扬州廿四桥。"]},{"t":"江神子 题潘兰老香海填词图","f":"古风","c":["探芳海外倦游鞭。","画中禅。","酒中仙。","问字乞诗，门限铁为穿。","陶写閒情搔短发，同雁泊，结沤缘。","风流张绪忆当年。","响商弦。","满南天。","梦醒吟壶，舞袖足回旋。","珍嘱茶花遗事曲，词史稿，莫轻删。"]},{"t":"丁香结 除夕，和梦窗","f":"古风","c":["辞腊鼍寒，供朝盘暖，婪尾婆娑曾醉。","忆剪钗红腻。","茸烂嚼、唾碧沾人衣袂。","绿窗梅盏咒，团圆会、故园梦里。","宜男羞舞，尚会好语，年莺深意。","今似。","守岁拚孤单，路数屏山未睡。","祭馁诗魂，占迟镜听，拥灯人背。","山静犹是太古，悄立无春地。","文君曾见否，留问南来燕子。"]},{"t":"玉楼春 甲戌清明","f":"七言律诗","c":["閒愁钻入诗心缝。","压得双肩寒未耸。","清明终是异乡春，风雨莫温游子梦。","羁魂不到先人冢。","阙处松楸谁补种。","潮音有意助新吟，泉路无人知隐痛。"]},{"t":"浣溪沙慢·登灵岩，依清真四声","f":"古风","c":["土石涌绀碧，烟霭延湖沼。","洞深径仄，争路交飞鸟。","残霸故国，一纸斜阳稿。","铃语浮屠悄。","凭吊数兴亡，野花零、江枫又老。","古春渺。","剩露井波澄，怅廊听落叶，径问旧香，事往吴山晓。","冷翠化云，飞上琴台秒。","勿妒天平貌。","妆淡抹浓时，学西湖、螺鬟更好。"]},{"t":"杏花天影·和姚景之","f":"古风","c":["绿云膏沐无心理。","向谁诉、分飞恨事。","蘸香鸳被半床閒，醉里。","晓莺啼，惰未起。","伤春地。","花萦步绮。","又轮指、番风第几。","梦辽何处汉家营，失计。","纵封侯，也后悔。"]},{"t":"丹凤吟 甲戌端午","f":"古风","c":["招得薰风驱暑，插艾门庭，下帷深寂。","菖蒲酒盏，漫掬流花自涤。","长添线影，閒情消尽，缠臂丝红，沈波菰黑。","拟起湘累问讯，近日湘江秋夜，龙啸消息。","堪笑钟馗倚壁。","脚靴手板须半赤。","面目嶙峋甚，算么么群丑，望风辟易。","吟壶清晏，阚室啸梁无迹。","门外黎邱千百变，搅一天风色。","天龙竖指，忘却魔眼擘。"]},{"t":"齐天乐 陪臞禅游西溪，约和梦窗会江湖诸友泛湖韵","f":"古风","c":["一溪依旧伤心碧，年年辄惊人换。","树合青连，桥横白断，曲曲柔波流怨。","山帘雨卷。","问窟宅何人，蜃楼红见。","代有词仙，素云沈后绪风扇。","芦花飞雪十里，旧秋新粉本，留付图卷。","名下低徊，尊前检点，都是营巢慵燕。","涓流似剪。","怕小影沧桑，海东三变。","引去蓬舟，暮烟凝棹远。"]},{"t":"水龙吟 惠山酌泉","f":"古风","c":["酒痕黯淡尘襟，茂陵渴抱看山病。","莺声招我，螺鬟笑客，溪回路近。","腰怯登临，眼馋苍翠，一池烟暝。","问山灵旧约，蹉跎十载，凭阑处，迷前径。","清绝吟魂待醒。","傲卢仝、香生瓯茗。","濠梁兴味，沧波身世，浮沈同证。","芒秃诗肠，芡磨菱角，老来心性。","向斜阳徙倚，峰巅瘦塔，伴臞仙影。"]},{"t":"木兰花慢 其一 苏堤春晓","f":"古风","c":["恨东风料峭，残红扫，扑珠帘。","正十里菰蒲，六桥杨柳，画出晴烟。","窥园。","董惟旧事，逗春心、破例罢芸签。","招我黄鹂三请，薰人芳草堪眠。","眉奁。","黛点螺鲜。","欣薄霁，惜暄妍。","早预约邻娃，踏青斗草，谢却云轩。","延缘。","鞦韆罢戏，整钗环、又上里湖船。","拾翠归歌缓缓，解酲病忘恹恹。"]},{"t":"木兰花慢 其二 南屏晚钟","f":"古风","c":["乍鸣琴蕉石，定香度，韵愔愔。","看欢喜岩高，净慈树古，翡翠开屏。","穿云。","金轮句就，未中秋、先有撞钟人。","空谷迟迟暮响，游人落落晨星。","西城。","续报鼍更。","鸥梦峭，马蹄轻。","杂山容水态，扉烟染紫，桥浪翻银。","飘灯。","客船夜半，比寒山、得句几诗存。","可是僧敲饭后，休疑路入山阴。"]},{"t":"木兰花慢 其三 断桥残雪","f":"古风","c":["煮羔羊美酒，销金帐，不知寒。","忽晓色通帘，琼楼玉宇，妆点湖山。","人閒。","梅花消息，指西泠、香在有无间。","重访段家故事，醉魂扶上雕鞍。","琅玕。","竹醉前湾。","招鹢去，伴鸥还。","看冰澌渐解，湖烟织半，峡水流三。","凭阑。","诗肩暗耸，怪吟髭、未老已先斑。","沽酒人过断块，停鞭客叩禅关。"]},{"t":"木兰花慢 其四 平湖秋月","f":"古风","c":["荡全湖暮色，莽空阔，浸寒光。","更吹老西风，山容减黛，桥迹微霜。","微茫。","白波无际，舞鱼龙、匝地泻银潢。","孤鹤横江掠影，几人击桨招凉。","鸣珰。","西子初妆。","桐叶响，彻东厢。","有晶宫幻出，珠光火齐，剑气干将。","鸳鸯。","倩他鹊影，作蓝桥、渡我涌金塘。","莫似琵琶浦口，浮梁来往参商。"]},{"t":"木兰花慢 其五 雷峰落照","f":"古风","c":["倒挥天外笔，巨灵手，写春晴。","看定后枯僧，残萝衲影，怖鸽铃声。","摇旌。","乡心枨触，欲登临、无路认归程。","夕照寻碑瓦砾，碧油车坠钿簪。","林坰。","逗我诗情。","烟紫合，嶂青凝。","纵湖山无恙，黄妃春梦，空付流莺。","城闉。","数声画角，待归鸦、虚掩侯潮门。","南北高峰月对，何愁树暝烟昏。"]},{"t":"木兰花慢 其六 三潭印月","f":"古风","c":["写空潭人影，有名曰，在中湫。","看桥板横弓，塔轮对鼎，今古长浮。","横舟。","琉璃界里，小浮图、烛影闪星眸。","卅六阑干曲曲，倚来偷看吴钩。","中流。","击汰吟秋。","尊易泣，笛方愁。","自东坡去后，琼楼恍惚，赤壁遨游。","更收。","孤山鹤梦，被西风、吹散落前洲。","诈识莼丝真味，此中惟有潜虬。"]},{"t":"木兰花慢 其七 两峰插云","f":"古风","c":["四围苍翠合，锦屏敞，列层岑。","忽马耳高骞，撑天尺咫，拔地千寻。","晴阴。","一开一阖，锁连环、中有暮朝云。","往返诸仙玉驭，不劳风伯清尘。","妆临。","镜俯湖明。","鬟竞绿，黛争青。","听高壑松涛，牙连海上，相向鸣琴。","飞楹。","行春桥侧，峙碑亭、南北路平分。","游客叠携阮屐，清宵分听缑笙。"]},{"t":"木兰花慢 其八","f":"古风","c":["一篙春水活，鸳鸯瘦，鳜鱼肥。","正梁环半亩，花飘坠饵，柳钓垂丝。","红稀。","芹香藻腻，涨春痕、泉脉接西溪。","今古濠梁此意，浮沈潮信相催。","苏堤。","天绘晴晖。","波滟滟，鹭飞飞。","有垂鳞逸叟，门藏桃坞，琴枕苔矶。","禅机。","夜寒不饵，笑鸬鹚、空自忍饥归。","江水庄周漫借，莼羹张翰空思。"]},{"t":"风入松 在梓舍决计入山，赋此","f":"古风","c":["归辽老鹤怯长鸣。","孤影零丁。","缑山惆怅中秋月，逢人漫诉离情。","争信天涯饮啄，余生分付蓬瀛。","园林图稿费经营。","尘梦今醒。","寻巢倦羽幡然去，何堪再问归程。","尚有閒枝小鸟，两三惜别啼声。"]},{"t":"无愁可解","f":"古风","c":["愚弄世人，造物何意。","悲欢离合生死。","乾坤一网罗，被笼罩、孰可避。","白发朱颜弹指事。","往矣流光流水。","不遇著、却相忘，遇着始见，老到我你。","忆昔总角嬉游，生如寄、蜉蝣外家檐里。","茑萝随树到，两母相随又逝。","觅食饥驱况往里。","冷暖相知才半。","雨窗话剪烛，真如梦醒，纵无酒、许心醉。"]},{"t":"解连环","f":"古风","c":["信音谁托。","思辽西冷月，雁天云邈。","算夜永、亲捣衣砧，乍寒到九边，怕郎衾薄。","迤逦征尘，梦屏山、客途难索。","想天青海碧，悔恨素娥，枉盗灵药。","封侯纵云绶若。","奈催人皓发，胡地笳角。","漫浪说、山北燕云，把閒草閒花，待总抛却。","故国荼薇，忍指栖枝残萼。","暂休吟、大旗日落。"]},{"t":"卜算子慢","f":"古风","c":["奔驹隙短，残蜡泪乾，始事闭门愁晚。","绝妙桃花，不比去年人面。","青盼。","忆丝杨、对我曾垂眼。","又粉碎恩仇，久被閒风閒雨吹散。","寂寞眠孤馆。","试吊古伤今，山遥水远。","百感苍茫，上界谪期疑满。","思遣。","种愁根、慧剑临风断。","独行传往，幽岩铲迹，伊人不见。"]},{"t":"踏莎行 题谭篆卿填词图","f":"古风","c":["阀阅蓬瀛，才华泰岱。","五陵年少驰车盖。","归来折节作词人，清辞白石分流派。","广雅门墙，清佳堂廨。","当年未审周吴在。","南园春结赏花盟，东风青荷垂杨睐。"]},{"t":"阮郎归 赋鼎湖飞水岩，和彊师纵舟楞伽峡韵","f":"古风","c":["珠玑颗颗出层坳。","和烟和雾消。","散花仙壁插云高。","花光皆白豪。","源滚滚，气飘飘。","岩根涛怒号。","尘寰谪坠为谁招。","玉人吹洞箫。"]},{"t":"曲游春 晓坐华严阁天阶，和周密","f":"古风","c":["暖翠浮岚里，罥千竿寒雨，往来莺织。","过院偷閒，惜流光偏在，奔驹一隙。","万绿红尘隔。","闻根净、人间筝笛。","看晓鸦、掠过西峰，点破锦屏山色。","短陌。","檀栾镐碧。","比姓字燕然，同此铭勒。","歌舞毡毹，梦花摇粉堕，麝飘香幂。","无分鸣钟食。","水云窟、自甘岑寂。","算片刻流连，并愁遣得。"]},{"t":"霓裳中序第一 小第落成，和羌个翁韵","f":"古风","c":["蛛巢爱网织。","罥树悬风露珠滴。","欲问经行踪迹。","径峭云深，耐人寻觅。","檐花夜湿。","任狼藉、蝶怜蜂惜。","谁念我、山深深处，鬼火照邻寂。","累石。","鳞排一一。","仍可负、墙东暄日。","山家终欠春色。","铭室新题，秃残江笔。","蜗庐真算得。","青山对、空尊任泣。","柴门倚、暮鸦归数，引我杖藜出。"]},{"t":"看花回 记少年事","f":"古风","c":["草草庖厨着意莹。","盘盎寒生。","携锄种菜荒田，认桂枝、量记窗棱。","少年无赖事，回首分明。","老觉岩阿有旧盟。","鹤友猿朋。","移泉烹荈收黄叶，好商量、画意诗情。","往来新认识，有个黄莺。"]},{"t":"玉漏迟 和元好问韵","f":"古风","c":["深山深窈。","飘零到处，寻巢樯鸟。","王谢雾家，月树南枝三绕。","不是神仙眷属，又不事、巢由同调。","君莫笑。","半椽抱膝，尽堪舒啸。","有人扰扰尘劳，騕袅金鞭，让他年少。","赌墅争湖，一局久经输了。","抱朴移家画稿，除点缀、胭脂残照。","山雨晓。","昔痕又增多少。"]},{"t":"睿思新·夜有绕庐而呼者","f":"古风","c":["少晴多雨天将坠。","这莫是、离群泪。","问阿谁、绕室高呼，似我思归还未。","七十流光逝水。","曾未梦、纸迷金醉。","卸双肩、两脚都轻，尚迟了、多时归计。"]},{"t":"青玉案","f":"古风","c":["天河倾向床头注。","梦惊断、江南路。","报到前溪新涨雨。","黄莺留客，碧山拦户。","且劝我、须臾住。","初阳黯淡窥松圃。","膏沐遍、宵来露。","莫向渔人频问渡。","千重云海，万重烟树。","犹见波涛怒。"]},{"t":"金菊对芙蓉","f":"古风","c":["絮帽团峰，波帘织洞，横溪约略阽危。","正僧归路断，樵语烟迷。","凭阑不见红楼影，望故人、风雨凄凄。","端阳节近，觞蒲角黍，乡味都非。","独客多在天涯。","问东劳西燕，怅怅何之。","话江南梦熟，往事依稀。","已知别后相思苦，更何堪、白发频催。","残英仍在，待携尊俎，尚及芳时。"]},{"t":"风入松 往来寮步道中","f":"古风","c":["古循州、道此分程。","车辙指东城。","畴人堆垛烦推算，合薰莸、一气氲蒸。","未领女儿香味，先仪将相雷名。","回途天气欠分明。","饤饾半阴晴。","此行非赴山灵约，试商量、圃学农经。","送客一轮月晕，愁予十里鸡声。"]},{"t":"苏武慢 丁丑端节","f":"古风","c":["续缕关情，书裙故事，年华又到。","丝菖酒面，角黍波心，老去无多怀抱。","还是闭门，曼引诗声，暗温词稿。","任遗钿拾翠，金鞭公子，歌呼沿道。","空见说、红荔湾头，流花桥畔，雷鼓云旗喧扰。","阑干波影，粉麝风香，十里暄阳芳草。","空巷近传，夜禁门迟，春台酺早。","讲水嬉深意，莫负湘江一棹。"]},{"t":"一落索 郴县道中","f":"古风","c":["终古郴江东去。","郴山长住。","住岂无情去有情，同隔潇湘浦。","况值黄昏梦雨。","玉京人苦。","峰能回雁不回郎，郎今夕、知何处。"]},{"t":"高阳台 寄题扫叶楼","f":"古风","c":["叶积庭深，楼空一渺，于今几度秋风。","芳草斜阳，难寻拥彗高踪。","芒鞋竹帚晨昏课，想俳佪、频绕芳丛。","似閒愁、扫去还来，未许雍容。","凄凉东海红桑老，算未秋摇落，已倒梧桐。","诗恐惊人，丹青寄慨情浓。","谢家春草池塘梦，园半亩、分付奚童。","客径迟开，一任云封。"]},{"t":"夜行船 宿鼎湖寺，怀慕经和尚。和梦窗宿化度寺韵","f":"古风","c":["香积炊烟楼碧树。","峰回转、草深春暮。","舍宅人遥，凭栏意远，报道云来封户。","老衲经行何处路。","问仙鹤、怎时化去。","几树梅花，一龛灯火，肠断人生晞露。"]},{"t":"解语花 游宜兴善卷洞","f":"古风","c":["千年古峤，问讯西风，几度停鸾鞚。","髻螺青耸。","幽栖处、竟许尘中人共。","鸿濛凿空。","通沅瀣、茅峰三洞。","云变幻、龙戏空高，尾坠吹天蝀。","大壑秋槎一纵。","怪银河无月，珠闇骊拥。","乳泉凝冻。","诗心洗、石气荒荒摇动。","蓬山待梦。","试先采、芝苗归种。","最堪怜、春压樵肩，半杜鹃红重。"]},{"t":"减字木兰花 为人题十年浪迹图","f":"古风","c":["十年瞬耳。","桑沧笑裂麻姑齿。","晏子狐裘。","抵债寻常入酒楼。","鹍鹏斥鴳。","大小乾坤皆过眼。","柳雪葭霜。","到处吾家第二乡。"]},{"t":"水调歌头 游焦山，和方回，平仄通叶","f":"古风","c":["形胜任争战，京口锁双丸。","蓬瀛清浅红尘，今已涨金山。","北固江山天限，南服衣冠人换，六代百年间。","一匹澄江练，尽处著烟鬟。","隐君庐，孤木馆，草芊芊。","华阳词翰，鹤鸣瘗石半钻刓。","带玉芝含鹿献，墨卷草疑蛇绾，真迹宝丛残。","水调中冷远，茶梦绕阑干。"]},{"t":"西江月 题谈月色画梅","f":"古风","c":["根自罗浮移植，居然绿萼仙踪。","纤纤十指透香风。","颠倒师雄一梦。","画石未须十日，消寒恰值初冬。","三分春色满琼钟。","亏得月明自种。"]},{"t":"八声甘州 题李云仙抱琴独立图","f":"古风","c":["问天风、海水自成连，于今几人听。","奈筝琶聒耳，村讴巴曲，波沸雷鸣。","遗事贞元剩谱，谁复问指琼。","岩石琴台路，霜月凄冥。","独有仙人绿绮，伴云涯倦客，身世伶俜。","剪高山流水，凌乱入丹青。","立苍茫、吟髭孤撚，宁韬弦、敛袖待晴清。","人间世、觉知音侣，惟有流莺。"]},{"t":"泛清波摘遍 邓尉探梅，和小山","f":"古风","c":["茅诛径小，杏傍墙高，莺报柳桃薰染好。","暖催寒勒，商略探芳计迟早。","行人道。","鹃声泪苦，驴足尘空，无意送春归去了。","倦侣高阳，重拾杯盘坠欢少。","雁来渺。","短札欲凭晚潮，何处始无芳草。","空怅秦淮渡昏，吴山云晓。","董笙渺。","立墓得句付谁，罗浮梦仙难到。","料想桂梢绿凤，为伊颠倒。"]},{"t":"倚风娇近","f":"古风","c":["巢鹤惺忪，探芳寒透心眼。","亸桥临水娇无限。","山驿暖风迟，乱蝶绕鞭丝，懊恼空枝，玉管休教吹散。","无奈啼鹃，频报时将春晚。","陌上还歌归缓。","醉倩香熏理花谱，情怀懒。","冷云湿翠襟分半。"]},{"t":"红林檎近","f":"古风","c":["枕絮偎逾湿，烛花寒更青。","月落鸟声悄，霜浓旅魂惊。","拼与分歧决绝，转许惜别叮咛。","泪波执手盈盈。","临语又吞声。","始上吴楚道，先见短长亭。","初阳木杪，摇摇鞭影分明。","江郎情黯，红楼回望，引愁一路云影平。"]},{"t":"菩萨蛮 为章松龄题家藏百鸟图","f":"古风","c":["空濛云水飞鸣地。","芦笋蒲芽春意思。","况少网罗人。","相呼云外群。","高依乔木宿。","下向横塘浴。","算有凤皇来。","追随君莫猜。"]},{"t":"喜迁莺 题太仓唐尚书万言疏手稿","f":"古风","c":["元气护，涕洟垂。","洛下又峨嵋。","厦倾犹有万言支。","廪不太仓糜。","士寒蝉，朝仗马，松柏挺风姿。","岁寒知我已迟迟。","何况没人知。"]},{"t":"倾杯乐 陈松英女生毕业纪庆","f":"古风","c":["山川盘郁，林峦胜处毓英雄。","有时閒气偏钟。","博白头衔不栉，盐白撒寒空。","陋井源双角，脂粉香浓。","惠泉九龙。","洗清思、更玲珑。","况济南、经舍家风。","南楼在望，想老人英俊，少年同生。","女好何羡罴熊。"]},{"t":"忆少年 题施肇曾松陵共证图","f":"古风","c":["宦游倦矣，逃禅逃酒，家园春色。","杨花最堪笑，老天涯为客。","继佛印、东坡非赤壁。","有衡阳、道元侍侧。","一襟软红外，剩松阴漾碧。"]},{"t":"酒泉子 题民族词选","f":"古风","c":["憔悴国魂，泪尽新亭人悄悄。","英雄未死胆肝粗。","拚头颅。","古今唯一，湘累沈沈呵壁叫。","是何多也醉乡徒。","乐华胥。"]},{"t":"女冠子 用牛峤体","f":"古风","c":["竹炉茶灶，落叶供薪风扫，昼眠迟。","云冷封吟屐，霜寒索破衣。","鬓丝禅榻畔，斋鼓梵钟时。","檐角蛛丝飏，客支颐。"]},{"t":"碧牡丹 用晏小山体，时近中秋","f":"古风","c":["司马非游倦。","身等嵇康懒。","飞絮游丝，罥树沾泥春晚。","偷得閒来，脚力欺人软。","好山好水缘浅。","春心眼。","济胜劳夙办。","空想游仙汗漫。","竿木登场，栈豆就恋嗟来饭。","故事缑山，鹤驭鸾笙天半。","翘首月明庭院。"]},{"t":"秋宵吟 丙子守岁","f":"古风","c":["灶符更，随籥转，腊鼓中分宵半。","签声寂、渐住换东风，铁衾初暖。","迓春盘岁盏。","白发羞簪人倦。","总堪叹。","似箭流光，年来偏短。","世事翻新，谁料得、风云夕变。","渭水西风，长安落叶，搅得酒肠乱。","江阔无归雁。","两字平安，寒缬望眼。","更何堪、无味尊前，游钓徒侣费检点。"]},{"t":"贺新郎 沈讱陈松英结婚志庆","f":"古风","c":["佳话登科小。","羡少年、洞房花烛，帐前欢笑。","草草良缘多成恶，郎性侬心未晓。","最难得、相当才调。","叶底双虫喁喁语，吐春丝、谱绣鸳鸯料。","红线系，三年了。","西溪模范从来好。","椀齐眉、相庄授受，伯鸾德曜。","仁学讱言惟山乐，寿与乔松共老。","旁莫妒、双栖文鸟。","两处相思今朝诉，嘱东明、漫许鸡人报。","恩共爱，两心照。"]},{"t":"沁园春 题唐天如所藏听帆楼扁额，黄宾虹图","f":"古风","c":["凭吊昌华，红荔湾头，蜃阁屹然。","念乩仙题馆，云来白鹤，留宾辖井，庭集青鸾。","东壁图书，西园杯杓，气象峥嵘势万千。","麻姑笑，洗荣华试看，沧海桑田。","云烟。","蠹简蟫篇。","只铁画、银钩三字传。","伴仲宣万感，元龙百尺，豪情拔地，健笔撑椽。","坐拥书城，门盈驷马，犹傍淮南大小山。","藏丹地，祝壑神呵护，毋憾宵迁。"]},{"t":"鹧鸪天 疝气发，入玛丽医院割治","f":"古风","c":["制锦操刀未勒勋。","伐毛洗髓又纷纭。","火烧木佛求灵骨，肠断巫猿悟脆身。","生死事，过来人。","五年巡狩记环循。","弹丸蕞尔江东窄，三割终须一掷沦。"]},{"t":"鹧鸪天·病中清明，不能省墓，为之怅然","f":"古风","c":["新种松孙未化龙。","寻常马鬣去年封。","年时客思清明后，今日魔缠病榻中。","生事悫，祭仪封。","终天犹恨海深同。","鹧鸪声里牛羊垄，况欠钱灰飏絮风。"]},{"t":"祝英台近 生日后二日作","f":"古风","c":["涧霞红，岩雨翠，消息又春暮。","多病文园，饯春已无句。","剧怜短鬓萧疏，今朝寒食，独搔首、云山深处。","为诉。","安仁正赋闲居，犹恐燕莺妒。","绮语妨禅，哀时又何补。","遥遥华胄元亭恨，终少高阳俦侣。"]},{"t":"玉楼春 题何沃泉偶然集","f":"七言律诗","c":["书香门第今南阮。","哭笋光阴春梦短。","珍珠百珧续收罗，余勇吟坛真可贾。","髯苏八叠专家擅。","君竟兼人论百算。","竿头进尺步雍容，韩信将兵多益善。"]},{"t":"浣溪沙 题王少梅得冯鱼山愤画斋题额","f":"七言古诗","c":["冯唐原是老丹青。","犹说云山画未成。","戏将积愤榜斋名。","公子太原裘欲敝，骚人邓尉笛尤清。","前贤手迹袭芳馨。"]},{"t":"鹧鸪天","f":"古风","c":["筋力登楼讵未知。","山高何况入云微。","虬龙许有随缘坐，猿鹤宁无入梦思。","层嶂合，一节支。","人方逸老我饥驱。","打包行脚前生定，拄杖归来梦亦蘧。"]},{"t":"最高楼 铁尊招饮鸡鸣寺景阳楼，读壁上题词，谱此继声","f":"古风","c":["楼一角，山色六朝收。","都是古今愁。","江流难洗胭脂辱，东风不识绮罗羞。","后庭花，新乐府，付渔讴。","唤不醒、繁华酒肉醉，鸣不散、乾坤风雨晦，人世事，海中沤。","绣襦辇路铜驼泪，乌衣门巷野花秋。","暖霜威，凭酒力，一诗囚。"]},{"t":"鬲溪梅令 题林岳威梅边读易图","f":"古风","c":["天机三十六宫春。","幻梨云。","香浸一尊，波绿欲生鳞。","微吟醒醉魂。","玉梅骨干雪精神。","个中人。","恍惚翠禽，声里唤真真。","天花黏著身。"]},{"t":"念奴娇","f":"古风","c":["芝荒鹤老，绝空山人迹，臞仙谁侣。","流水小桥天欲晚，可惜落英无数。","寒食单衣，江城哀笛，悽咽欺花雨。","问谁索笑，冷香薰透诗句。","宵来梦入罗浮，翠鸟殷勤，促我摇鞭去。","算到江南春赶上，又唱送君南浦。","三嗅芳馨，一番惆怅，恨不香中住。","残阳虽暖，湿云尚拥归路。"]},{"t":"绕佛阁 别情，依清真四声，与唐圭璋同作","f":"古风","c":["黛眉翠敛。","人去语寂，春黯甥馆。","亭堠长短。","夜来梦醒，孤身在罗幔。","袖华泪满。","边塞万里，还胜天远。","金缕纤婉。","倩伊引惹，归舟系岸。","旧识晏如客，砌影偷量长比线。","慵懒弄妆，残脂犹涴面。","变镜里华容，年逝如箭。","那堪人见。","奈状我相思，云鬓蓬乱。","抱鸳衾、半閒偷展。"]},{"t":"菩萨蛮引","f":"古风","c":["股从蓬剖。","泛南溟旁附，大罗星斗。","怕梦醒、梅雪清寒，趁挥汗远携，听鹦柑酒。","再入华胥，落老子、青牛西后。","奈虚庭眠雨，几把芒鞋竹杖轻负。","村禽唤晴谷口。","道溪流壑瀑，虾跃雷吼。","试相与、身入烟雨图中，尽湿翠痕痕，冷透襟袖。","龙抱珠回，笑梦恋、桥尘依旧。","问山灵、仙家蝶使，知侬到否。"]},{"t":"点绛唇 宿竹林寺，有怀钱仲联，酬其赠别词也","f":"古风","c":["虫咽僧窗，前番离绪今宵絮。","蠡园鼋渚。","都是寻诗处。","梧柳楼头，商略黄昏雨。","今何许。","嵩云秦树。","一例相思句。"]},{"t":"诉衷情 用温飞卿体","f":"古风","c":["水远山远。","斜照晚。","画桥西。","帘篆悄，黄鸟背人啼。","去路梦中迷。","俳佪。","陡闻邻马嘶。","讶郎归。"]},{"t":"水龙吟 中秋夕陪秋园柳亭步月，登粤秀山","f":"古风","c":["故乡原有千秋，从今不信西湖好。","楼台倒影，街衢泼水，时忘昏晓。","夹路歌声，万檐灯火，市喧争闹。","更莺簧麝馥，相扶笑语，双飞晏，珍丛绕。","惊心故候旧事，抚青萍、倚阑人少。","飘零大树，沈埋遗镞，西风秋草。","鱼贯随流，雁行踞石，呼銮古道。","愧同游赤壁，兼饶酒客，让东坡老。"]},{"t":"高阳台 陪邬碧泉刘一佛李作屏茶话，北郊吊绍武君臣冢","f":"古风","c":["桥咽花流，碣凭藓篆，苍蝇吊客仍稀。","去矣王孙，萋萋芳草霜欺。","烽烟岭外惊人讯，马首尘、偏向江西。","小朝廷、几日君臣，共穴狐狸。","江山又觉今非。","甚弹丸黄土，尚占天涯。","风雨灵旗，几多猿鹤飞驰。","杜鹃红到荒坟角，学粤讴、北客题碑。","祝山灵、大壑藏舟，莫任宵移。"]},{"t":"踏莎行 题陈文忠公遗集","f":"古风","c":["宣室危言，神京惨变。","江湖魏阙臣心恋。","南园后抗古人风，西门归死慈亲面。","圜户琴歌，云淙词卷。","书香几为耕锄断。","珠江老蚌吐光芒，历年三百今重见。"]},{"t":"引驾行 穷新界深阻处觅可居地，得之。用屯田韵","f":"古风","c":["溪痕添雨。","山妆罨翠层峦暮。","鹢孤飞，鹂三请，田田叶荷晴举。","遥睹。","尽兽石嶙峋，蛇流宛转赴前浦。","渐天黯、苍茫一片，没人家，止烟树。","尔许。","流莺引路。","野鹤幽巢相遇。","定十笏芟荒，团瓢结个，孰云孤负。","环视如此云山，不堪栖隐又何处。","总胜似、残蓬寸梗，逐风波去。"]},{"t":"长亭怨慢 丁丑生日作","f":"古风","c":["且谩怨、断烟离绪。","蓬梗生涯，陌头东路。","瞢绿痴红，旧痕襟染剡溪暑。","蠡湖风月，曾助我、新调谱。","猛忆故园春，促归思、桃花飞雨。","迟暮。","过东邻垆畔，怕问旧游俦侣。","灯花鹊喜，好消息、总归无据。","试巡遍、芷屿兰汀，好拣个、沙鸥眠处。","谅浅薄阴晴，易乞东君容许。"]},{"t":"向湖边 新筑近泉源，策杖往听，坐卧巨石上，衣袂为湿，拂拂寒生毛发间。拟作草亭覆之，一邱不可专，一壑居然我有矣","f":"古风","c":["腹稿林峦，首邱云水，弹指须臾即现。","泉脉蜿蜒，费芒藤寻遍。","喜霎逢、龙吻飞珠，蛇鳞赴万，音韵琤瑽千变。","倦客临流，比依松多健。","濯足风前，快慰扶桑愿。","休再恼，听孺子、沧浪歌怨。","状谱清泠，洒肝肠寒战。","问出山、忙碌凭谁劝。","暂留我、清涤可怜面。","凉沁苔扃，胜淞图分剪。"]},{"t":"花心动 环居植竹蕉梧桐","f":"古风","c":["空谷红稀，层峦合、中有团瓢阴影。","听雨朱楼，扇暑无庭，怎许眠琴三径。","袖寒天、绿栖鸾渺，奈恨上、萼眉悽损。","仗翠管、书愁怎得，挹泉金井。","艳羡潇湘一境。","奈鹿梦都虚，凤巢难稳。","暍息茂林，脆悟空身，燕蹴冰弦人醒。","待环万绿蒲团外，报风雨、兼秋做冷。","算春到、繁华锦城懒问。"]},{"t":"齐天乐 三洗潭。洗耳洗心洗梦也","f":"古风","c":["问谁倒挽天河水，朝朝傍檐飞舞。","乍咽笙簧，旋锵珠玉，忽有东来山雨。","凉柯倚处。","似飘袖风栏，湔裳烟渚。","息影临流，尘襟抖擞尽无暑。","涧阿有人漱石，奈啸歌寤寐，常绾尘绪。","蒲辙临门，鹤书度陇，消得黄粱炊许。","南柯院宇。","恋瞬息繁华，知谁宾主。","洗梦都清，邯郸醒后苦。"]},{"t":"凤衔杯 茅后有树圆如张伞，粗干横出，可偃坐远望","f":"古风","c":["文园消渴荫凉柯。","盖亭亭、舞影婆娑。","却喜风来，筛影碎金多。","防暑到密张罗。","随白鹭，睇沧波。","岛浮沈、出没鼋鼍。","两两渔舟，出水若穿梭。","织罢日西矬。"]},{"t":"临江仙","f":"古风","c":["天光照夜生苍白，小楼倦客孤灯。","风声泉韵未分明。","铿锵环佩，疑降许飞琼。","白发欲凭山色染，倚屏坐破浓青。","拟将心事诉流萤。","招招罗扇，迤逦没深箐。"]},{"t":"风入松 宿昌平农场望楼，用赵彦端体","f":"古风","c":["槎枒胸次郁峰峦。","块垒谁删。","平芜换目皆空阔，莽苍横眺无边。","隐隐斜坡扑地，双双华表撑天。","糖多小令拟裁笺。","列蔗成田。","浓甘佳境今方酿，侧生旁挺盈阡。","最羡斜阳芳草，让他老犊閒眠。"]},{"t":"风入松·息矮岭冚松林，用梦窗体","f":"古风","c":["疑听蛮海骇涛声。","风静也长鸣。","万龙夭矫拿云动，露爪鳞、薄暝初晴。","头上绿天漏处，碎筛点点繁星。","停鞭倚仗影零丁。","衣袂峭寒生。","尘缘愿为从游弃，奈留人、总是青青。","移入画图犹欠，溪流并个茅亭。"]},{"t":"醉花阴 寄题夏臞禅谢池新居","f":"古风","c":["邺苑图书归插架。","棠棣阴连舍。","省得买山钱，一片新阴，浓覆鸳鸯瓦。","我亦诛茅堪歇夏。","邻傍谈禅社。","容膝即云宽，况有天眼，花竹饶而野。"]},{"t":"月中行 题爪哇陈寒光天上人间集","f":"古风","c":["披襟岸帻老疏狂。","秋叶为诗黄。","沧波呜咽断人肠。","沤没不成行。","余情分付凭烟水，况又有、燕语回樯。","泠泠湘瑟海风长。","无字也悲凉。"]},{"t":"望江南 题北流陈柱尊萝村读书图","f":"古风","c":["天地窄。","无处著吟身。","鼙鼓声中人顿老，棋枰换后劫逾新。","海上又扬尘。","回首望，萝月澹村唇。","寂寞空山今亦古，短长寒檠暖于春。","招隐有南云。"]},{"t":"阳春 戊寅元旦作，用家无咎体","f":"古风","c":["黯山居，偏寻到，赖有好春知我。","日历久删除，余寒凝、檐鹊何事尚庭贺。","桃符椒颗。","权换却、炉香经课。","楼外怕见沧波恶。","屏开又倩云锁。","奈风雨、阴霾天为堕。","撩梦乱、山人稳卧。","绕篱花幡力薄。","付回潮、卷地红涴。","重关未算计左。","聊料理、齑盘蔬锉。","祗辛苦、几个渔樵辈，苍茫点破。"]},{"t":"长相思 一月廿三日山中始见桃花","f":"古风","c":["忆桃枝。","见桃枝。","人面春风笑语非。","天寒翠袖时。","怕人知。","没人知。","待我知时花已稀。","武陵寻梦迟。"]},{"t":"鹧鸪天 病疝入医院割治，愈后出院作","f":"古风","c":["眼隔青山未四旬。","缘何猿鸟便生嗔。","饿鼯閧夜翻残檠，黏蠃题门篆古尘。","垂大觉，再逡巡。","天教留我作词人。","一朝跳出修罗网，赢得狂佯又几春。"]},{"t":"婆罗门引 山居补植花木","f":"古风","c":["庐非人境，山深四月未闻莺。","飞花空忆春城。","最恼无情野烧，收拾到陈青。","尽黄云红叶，一望芜平。","荒畦几棱。","豆坼甲，怯寒轻。","剩有劫余幸草，识我经行。","饾饤阴晴。","试种竹、移蕉环护庭。","锄未了，雾冥冥。"]},{"t":"摸鱼儿 戊寅五月五日哭惠文女","f":"楚辞体","c":["黯江城、落梅哀笛，吹残甥馆琼树。","臂丝续命欺人耳，乍面忽成千古。","鸡报午。","莫便认、视阴灵照机先赴。","昙花两度。","恁一坠银瓶，永辞珠掌，先后委尘土。","人间世，生女生男何补。","漫云光采门户。","母兮抚汝终如始，藐尔诸孤谁抚。","天欲暮。","偏教我、临流踯躅横舟渡。","蒲觞忍举。","对渺渺蛮波，年时角黍，怕听大招赋。"]},{"t":"浣溪沙","f":"七言古诗","c":["烟雨霾天雾隐山。","苍波无语对愁颜。","孤灯促我掩重关。","蔬果虫余分脆润，缥缃蠹后理丛残。","牟尼一串算消閒。"]},{"t":"过秦楼 彩蝶大逾掌，夜入天如书斋，扑而乾之，制为标本诧客。正香江人满时也","f":"古风","c":["花国春悭，虫天劫换，末路凄凉如此。","香非迷客，望辄投门，一误遂成九死。","幕燕池鱼正愁，游戏忘怀，人间何世。","算山空月坠，尘缘蝉蜕，蒙庄醒未。","似见说、猎火烧原，随萤逐燕，省识蛮江风味。","容台铢袂，罗洞蕉裳，蛋雨狼烟夺绮。","恨不蓬莱峤壶，埋迹栖幽，避嚣辞市。","奈身文贾祸，碧血斑斓茧纸。"]},{"t":"虞美人 双树居赏月","f":"古风","c":["故乡明月团圆面。","终隔缑山远。","安排诗酒待清光。","无奈满城风雨似重阳。","平安园竹僧无信。","难向天涯问。","嫦娥不肯下云来。","为怕青田碧海涨黄埃。"]},{"t":"东风第一枝","f":"古风","c":["暖玉埋香，嫣红堕粉，返魂漫借风力。","早知阆苑前身，莫信仙山咫尺。","蓝桥久断，又何事、银河重隔。","睹生绡、摇荡秋魂，恍听佩环今夕。","归正缓、花开绣陌。","人宛在、春生彩笔。","痴心欲唤真真，妙手偏开七七。","摩挲老眼，疑错认、罗浮仙客。","怕无端、邂逅相逢，又结他生缘迹。"]},{"t":"渔家傲 和六禾夏夕偶成之作","f":"古风","c":["无味蒲觞唇怯涴。","雨余泪阁榴花朵。","风颤灯檠如豆火。","思量过。","古欢随梦醒前堕。","睡既不成行复坐。","教经懒事调鹦课。","明月中庭今算可。","朱樱颗。","床前又渺红绒唾。"]},{"t":"渔家傲","f":"古风","c":["写罢春怀余墨涴。","长吟颤动金钗朵。","烛外煎愁榴似火。","嫠蟾过。","隔墙林影穿帘堕。","独自薰香还独坐。","重温旧梦成功课。","排遣千端无一可。","山饭颗。","杜陵诗里寻残唾。"]},{"t":"渔家傲","f":"古风","c":["剩得征衫梅雨涴。","青灯赚我花垂朵。","桃柳风烟榆枣火。","隙驹过。","故乡归梦屏山堕。","南面书城围促坐。","宵分未了丹雠课。","琴素经金聊自可。","丁香颗。","咒郎移烛思芳唾。"]},{"t":"渔家傲","f":"古风","c":["修不成书笺欲涴。","押花漫诩云成朵。","閒语閒言都付火。","余酲过。","燕泥惊梦琤然堕。","拥髻背灯愁默坐。","金钱枉卜重逢课。","不识相思犹自可。","珠跳颗。","字沾红泪封黏唾。"]},{"t":"渔家傲","f":"古风","c":["细认杭襟痕旧涴。","记曾侧帽簪花朵。","悟彻浮生蛾赴火。","都尝过。","咸酸味海教人堕。","春去园林筵罢坐。","闭门领略閒功课。","灯影娟娟花可可。","千万颗。","檐珠的砾茅龙唾。"]},{"t":"渔家傲","f":"古风","c":["泉水在山泥未涴。","出山时恐污莲朵。","罗刹罡风尘劫火。","等閒过。","昭昭身世冥冥堕。","借得蒲团初学坐。","牟尼权作晨昏课。","翠竹黄花期印可。","明珠颗。","晶宫严护骊龙唾。"]},{"t":"渔家傲","f":"古风","c":["红粉未教山色涴。","仙人或有花三朵。","邈矣滥残煨芋火。","天风过。","林间数杵疏钟堕。","种得幽篁供独坐。","归来莫补空囊课。","寒菜一畦秋病可。","餐玉颗。","疗饥桂子嫦娥唾。"]},{"t":"八声甘州 读半塘翁词，觉气象苍莽，具潮海之观。怀其人而悲其遇，因效其体以吊之","f":"古风","c":["料苍天、付托要词人，搜寻软红间。","见鼎钟肉鄙，版靴尘俗，清气都难。","唯有能言鹦鹉，喉舌惯翻澜。","教谱清平调，勿唱家山。","说树禁言温室，又谏书夜写，剩稿灰残。","算塞戈廷杖，赐不逮华颠。","荡蠡舟、五湖烟水，尽逍遥、消啸满南天。","摊定稿，幸灯花落，半字僧完。"]},{"t":"卜算子 为郑霁林太守题先德辅堂先生淞江泛艇图","f":"古风","c":["抛却薄书来，暂理丝纶事。","鲤鱼风起露莼香，渔唱里，诗成未。","一棹远红尘，即是桃源地。","世许烟波有钓徒，我欲剪，松江水。"]},{"t":"唐多令 山中茅居，近悟瓦为不漏之理，物料毕集，阻雨待晴","f":"古风","c":["缘觉耳根知。","溪声摇梦思。","奈痴云、总是迷离。","未到上灯先闭户，斋静课，槿葵稀。","破屋杜陵诗。","秋风防我欺。","燕巢泥、扶上梁迟。","疑是茅龙衾恋旧，犹未肯，换春衣。"]},{"t":"贺新郎 郑师许自北流萝村来书，并题双树居词，依韵奉答。书云：近熟读辛苏调，已和贺新郎全部，故及之","f":"古风","c":["何处容吾钓。","况年来、虫天尘劫，支鸿孤矫。","沽酒典衣聊作达，我大乾坤自小。","呼牛马、从人嘲笑。","尝惯风波蓬梗味，细思量、毕竟无家好。","游傍海，狎鸥鸟。","别来霜鬓知多少。","喜见说、豪情胜概，辛苏同调。","唱遍贺新郎百曲，依样葫芦画了。","拥突骑、渡江横扫。","破碎山河凭收拾，盼英雄、唾手黄龙到。","咬文字，令人老。"]},{"t":"凤凰台上忆吹箫 中秋夕山居无侣，月色又复黯然，酒兴诗情，消歇殆尽。和霞公韵，补成此解","f":"古风","c":["云叶丛阴，烟丝织暝，鸣秋声噤霜钟。","碧海青天何恨，吊影愁侬。","莫是不堪回首，故园月、偏倩尘封。","空延伫，山深夜响，桂子零风。","回溯旗亭旅况，算争传水调，谁与纱笼。","今才算、巢营垤蚁，衣换茅龙。","遥望隔江烟火，归梦绝、倦眼惺忪。","嫦娥笑，霜髭留伴凫翁。"]},{"t":"浣溪沙 妙高台登高","f":"七言古诗","c":["罥雁丝云凝不流。","碧天如水绉纹柔。","风怜白发帽栖头。","世变须弥弹指现，战场秦汉及身游。","黄花憔悴紫萸愁。"]},{"t":"蝶恋花 酬崔伯樾和韵","f":"古风","c":["尽揽秋声归笛里。","费买山钱，托迹壶中地。","萝月肩寒云面起。","衣襟满挹空林翠。","丛桂小山招隐意。","猿鹤前盟，燖冷都多事。","离乱亲朋疏雁字。","东坡谁问渠生死。"]},{"t":"醉蓬莱 九日预祝六禾生日，和霞公韵","f":"古风","c":["傍战场菊花，酒国萸香，饥肠回九。","鬓短簪花，笑婆挲盈首。","萍梗风波，桑榆晷刻，算岁寒相守。","赢得而今，风尘面目，庐山依旧。","异域重阳，陶篱无恙，晚节孤香，堪供三嗅。","摇落天涯，似灵和移柳。","有客悲秋，非公不乐，笑胡卢开口。","六穗嘉禾，黄花明日，伴人清酎。"]},{"t":"一剪梅","f":"古风","c":["欺枕西风怯夜寒。","颤豆灯危，吟纸窗乾。","萧萧落叶满长安。","马影鸡声，几个人閒。","梦里乡关屏上山。","咫尺天涯，杜宇声残。","夕阳无语下阑干。","雁字云笺。","尽写愁难。"]},{"t":"八声甘州 秋夜怀人，上夏师北平","f":"古风","c":["自西山、王气一消沈，幽人下重关。","管园林春绣，燕莺晨闹，自铸词仙。","万里麻鞋犹在，韩石枉磨刊。","岭海听潮梦，帆影鸥边。","绿野凄凉门馆，剩灵光屹立，鲁殿年年。","算长安落叶，残月媚吟笺。","听津沽、渔村烟语，到黍离、草蔓总悽然。","山深处，望金台树，北斗依难。"]},{"t":"昼锦堂 六禾出赠冼玉清女教授词相示，适求其作双树居图未成，和以促之","f":"古风","c":["瘦句黄花，清辞风絮，仙骨珊朗瀛蓬。","想是坤舆灵毓，通理黄中。","高凉门楣双节虎，顾张闺阁一声鸿。","皋比座，续史大家，绕墙桃李花红。","鸣凤。","蛮海曲，枳棘寄，差池远避狼烽。","见说依刘垒燕，为叶图龙。","丹青双管春生角，珠玑百琲谱调宫。","相如壁，突屹生堂枫树，待种邮筒。"]},{"t":"声声慢 木芙蓉，同六禾作","f":"古风","c":["蜀垣围锦，孟帐渲罗，香薰气暖逾春。","采涉江迟，芳搴木末湘魂。","宿妆脂残粉，剩倚阑干，总是娇颦。","衣裳想，拟唐宫吴苑，醺醉晨昏。","何事颜客百变，学鹅黄装好，又换蛾螓。","性本宜霜，拒霜错唤词人。","专城众仙有约，主群芳、何地移根。","寒讯急，冷枝头、结子梦痕。"]},{"t":"霜花腴 咏雁来红","f":"古风","c":["霜花糁白，醉晚枫、凭谁共斗酡颜。","秋雁峰回，春鹃魂返，千林染泪斑斓。","半青半丹。","骗雾中、老眼偷看。","讶金风、嫁杏妻梅，天孙聘锦奠西园。","袅袅枝头霞举，认含芦吮笔，艳写云笺。","望断衡阳，书传塞北，红情几叶缠绵。","月明在天。","警霜心、何让韶年。","奈南楼、破梦声声，误人花抱眠。"]},{"t":"瑶华 垂丝海棠","f":"古风","c":["何来蜀客。","队逐群芳，踏浅红南陌。","垂垂老去，须纵嫩、漫说拳丝非白。","春风西府，照妆烛光分邻壁。","正酣歌、千缕金衣，奚待天孙机织。","诗人吴楚分明，袅一线临风，腰舞无力。","归从海外，草木记、平泉能识。","穿莺缀蝶，笼不住、杜陵题墨。","莫浪评、有色无香，毛举纤微头责。"]},{"t":"孤雁儿 和范仲淹韵","f":"古风","c":["羁孤人影依庭砌。","寒到耳，边声碎。","汉关秦塞路漫漫，问汝离群何地。","哀鸣谁诉，寒栖谁管，明月潮千里。","江皋木脱枫林醉。","拆翼处，都沾泪。","西池鸳梦让梁温，独饱江湖风味。","鲤鱼波恶，鹰鹯尘涨，又怎生逃避。"]},{"t":"玉胡蝶 己卯冬至","f":"古风","c":["候气灵台何在，鲁郊云物，弥觉苍黄。","赋罢悲秋，动人广漠风凉。","生机兆、菖蒲空卜，钻火改、榆枣延望。","楚魂伤。","梁园授简，难写愁肠。","蛮江。","栖迟何事，孤禽怯月，旅雁惊霜。","无赖持杯，辛盘徒为借春忙。","蛩更絮、残灰知冷，驹隙驰、一线添长。","水云乡。","寒衣夜索，凭吊鸿光。"]},{"t":"江南好 翠林寺园小集","f":"古风","c":["蜜冷蜂枯，藤缠虬老，满园暖翠栖烟。","玉鸣兰佩，摇落夕阳边。","刻画金围成带，腰瘦损、复倩谁怜。","閒庭院、诗情画意，难得是荒寒。","祇林金布地，麻姑长爪，擎起诸天。","又金刚神杵，龙制安禅。","偶集江鸿海燕，来同听、云鹤山猿。","还又见、题诗扫石，咳唾落珠圆。"]},{"t":"霜叶飞 山居门前双乌桕树饱霜递零，叶叶作胭脂色，缤纷篱落间，依梦窗四声","f":"古风","c":["理愁无绪。","酡颜对、吴霜酣饱双树。","半生枯稿惯悲秋，膏泽违春雨。","算落叶、翔空万羽。","江村图画疑晞古。","讶澹泊人家，买到北燕支，盖尽石阑寒素。","闻道径石停车，枫林坐晚，冷色薰透吟赋。","炫天霞彩照东篱，更絮寒鸦语。","久隔鲈莼脍缕。","烹湘休遣残红去。","望待偿、明朝愿，厚积阶茵，醉供眠处。"]},{"t":"意难忘 春情，效东坡体","f":"古风","c":["春满金阊。","记流花波暖，梦草魂香。","杯深忘约浅，烛短负宵长。","朝送客，耐思量。","是月貌云裳。","似身经、瑶池秘殿，琼岛西厢。","漫云萍水他乡。","胜江皋佩约，堂宴钗行。","余欢容细嚼，后会费相商。","今日事，断人肠。","竟山海微茫。","纵天公、量珠未许，再见何妨。"]},{"t":"花犯 和六禾鬓梅作","f":"古风","c":["小横斜、金钗坠凤，双拖破灯晕。","宝云盘鬓。","忆雪月迷离，故遣郎认。","厚帘密护寒犹紧。","涵春瓶案稳。","更九九、傍奁图展，消寒期取准。","撩鸦簪拔卜行人，江南路、莫奈寄枝留恨。","梳先懒，飘零怕、玉龙流韵。","宫妆卸、嫩黄未褪。","移点额、工夫陪倦鬒。","兆结子、眉痕归画，思君频领引。"]},{"t":"贺新郎 惠侨自萝村寄示王玉章先生和题双树居之作，叠韵酬之","f":"古风","c":["海角寒江钓。","计有时、打包行脚，杖藜轻矫。","坐破青毡金梁梦，犹是雕虫技小。","近另惹、壑嘲陇笑。","买得沃洲充小隐，枕蛮云、忘唱江南好。","劳远客，门题鸟。","尘中自是知音少。","更难逢、周郎一顾，许赓同调。","婚宦从来都是误，又被云山误了。","愿开径、落花春扫。","丁嘱鸟猿迎门者，候碧鸡、祠使轩车到。","毋任我，烟霞老。"]},{"t":"瑶华 和山居琼花作","f":"古风","c":["舞衣拖縠，珠佩披离，斗嫦娥腰束。","风来瑶圃。","仙梦里、恍见瀛洲雨玉。","飞琼何事，降洛浦、凌波仙躅。","只翩然、雪氅霓裳，妒煞瘦红肥绿。","年时一梦扬州，忆釐观巡檐，也曾三宿。","依稀酒醒，瑶钗坠、月影横斜茵褥。","绿竹无分，梨云拥、石崇金谷。","到而今、曝褐岩扃，粉捏纪游镌竹。"]},{"t":"江南好 吊钟花","f":"古风","c":["流水琴时，空山磬后，霜鸣洛浦沈铜。","阴阳炭铸，复倩兽炉烘。","瓶换清泉暖衅，残霏洗、月影玲珑。","遍排处，枝悬个个，小叩待飞虫。","池塘蛙鼓吹，莺簧蚓笛，同哑西风。","喜伶伦涷色，嶰谷霞红。","鼎食南柯梦境，任迟度、午饭帘栊。","春深了，花铃自护，新叶绿云重。"]},{"t":"齐天乐","f":"古风","c":["古今圆月终须缺，死离悔轻生别。","数米秤盐，偎寒让暖，耿耿此情难灭。","行装打叠。","忆催起荒鸡，出门波阔。","细语丁宁，依稀心事尚能说。","蓬莱方士漫觅，十秋经间隔，铸憾成阙。","爪去留痕，魂来除梦，怎梦近时都绝。","年涯再阅。","愿永忏情天，昆灰消劫。","旧债才清，后缘休再结。"]},{"t":"声声慢 己卯除夕","f":"古风","c":["钟声催句，笠像题图，消磨残剩光阴。","腊鼓催年，山人庭户愔愔。","戎家约悭守岁，酒赊来、婪尾孤斟。","寒不寐，想花街裙屐，阗溢江浔。","渡海东风旧织，著篱桃红笑，尚趁冬深。","露布昆仑，先期有客关心。","故园绮窗梅竹，讯平安、镜听烟沈。","书城夜，又蛮春、空老蠹蟫。"]},{"t":"水龙吟 凤皇山居旁营生圹，漫赋","f":"古风","c":["词仙宜占名山，一坏净土还吾待。","灯残酒罄，钟鸣漏歇，川终归海。","生岂无涯，死如有约，例难逃外。","况老夫耄矣，咸酸饱饫，纼将绝，骖加骇。","荷锸刘伶留诫。","遇青山、何须价买。","无分归元，生防痊骨，临时狼狈。","掘为狐狸，窟营兔近，身焉是赖。","付啊唯厮守，马塍花事，有蛮春在。"]},{"t":"浣溪沙 庚辰元旦","f":"七言古诗","c":["到底春风不世情。","偏来涧户扇娇晴。","唤醒尘梦借溪声。","夜雨味温黄卷似，陈根芽竞白髭生。","书痴依旧恋灯檠。"]},{"t":"浣溪沙","f":"七言古诗","c":["地异桃源亦自仙。","权为藕孔避兵人。","洞猿野鹤许忘年。","鬓色莫凭林色染，泉声何似杀声寒。","又防流去作狂澜。"]},{"t":"探芳信 元夕，和梅溪","f":"古风","c":["箭催晓。","正灯绽宫花，裙拖烟草。","忆洛城三五，香尘软风扫。","沸天箫鼓红霞闹，暖入莺声早。","水云乡，漫掩重关，九边春到。","报道。","雁来了。","带露布欢声，慰人愁抱。","故事昆仑，重搬演、排场好。","遗簪堕珥香狼藉，错认鳌山小。","广陵游，一梦蛮江坐老。"]},{"t":"绕池游 唐圭璋自蜀寄题双树居词，依韵酬之","f":"古风","c":["渺繁华梦，回首蛮荒投老。","春渐暮、伤心花事了。","云乡水国，只有相依鱼鸟。","吟壶天小。","到门峰绕。","水仙琴操。","聊学孙登长啸。","黄龙事。","惆怅鱼鸿杳。","题门烟晓。","飞到阳春高调。","千里明月，屋梁落照。"]},{"t":"选冠子 为冼玉清女教授题手拓邝湛若先生玛瑙冠图","f":"古风","c":["入地沈沈，切云岌岌，明福潜光重灿。","岸帻吟风，投簪遁世，有约罗浮虚愿。","海雪堂空，二雅音微，一琴血溅。","算南冠不死，红羊劫后，流花波咽。","曾见说、名士天涯，蛮娘云亸，犵鸟獐花昏旦。","撄锋免胄，结带殉缨，惹起琅玕镌怨。","晞发楚魂，栉沐高凉，芳薰钗钿。","况弁髦非敝，膏泽留遗手篆。"]},{"t":"尉迟杯 江楼春集，用无名氏体","f":"古风","c":["灯轮艳。","怎蛮乡、丽景今夕欠。","鼓鼙隔岸声酸，桃李渡江春淡。","无情阑槛。","拦归梦、莫越同天堑。","借消磨、剪碎珠城，登楼休说多感。","有时狼藉杯盘，真孤负雄谈，慷慨说剑。","织锦机丝，飘花烛泪，似滴临歧鲛点。","排愁去、依前销黯。","酒颜半、愁多红为敛。","恨斜阳、暮角催归，一路凉飔迎靥。"]},{"t":"扫花游 早春喜雨，和梦窗春雪韵","f":"古风","c":["乾封天意，忽斗柄阳回，新寒料峭。","柳丝暗袅。","似冥濛弄色，龙池春老。","净洗诗肠酒榼，登亭赏晓。","理吟棹。","拟沿溪耐春，花讯刚到。","野色青缥渺。","更岫湿钗鬟，波翳菱照。","约虚斗草。","尚重衾梦恋，小楼深窈。","破块鸣条，繁露升平旧调。","润酥早。","嘱檐娘、迟晴休扫。"]},{"t":"丹凤吟 社题，和清真","f":"古风","c":["春懒花慵时候，听雨红楼，眠云山阁。","冲帘归客，泥滑燕衔巢幕。","烟先漾晓，游丝横路，润迫琴喑，寒欺衾薄。","故国红楼旧梦，海外东坡，醒后还在天角。","不断怪风掀浪，恼人但觉桃汎恶。","一曲公无渡，听箜篌弹罢，情意消铄。","飞花飞絮，等是去家流落。","枉说忘忧歌采采，任芳馥盈握。","愁思百遍，抛却为上著。"]},{"t":"烛影摇红 花朝","f":"古风","c":["今问花神，生何偏诞春之半。","风暄日暖燕莺晨，忙煞閒庭院。","料理探芳心眼。","锦城游、归歌缓缓。","时光正好，百舌无端，浪评长短。","客思天涯，踏青望里钿车远。","青袍白袷试春衣，邻户闻裁剪。","挑菜人来步懒。","怅泥深、啼鸪语怨。","三分有二，春色无多，斜阳催晚。"]},{"t":"水龙吟 寄题岑学吕师尚室双牛图","f":"古风","c":["长林丰草生涯，落花香著高眠地。","读书挂角，触墙成字，诗鸣宫徵。","文绣何荣，泥涂何辱，生防烧尾。","记五羊旧梦，服箱负轭供鞭策，从穿鼻。","犁雨耕云非计。","望吴蟾、惊心喘气。","骑来步稳，清泉白石，犊孙游戏。","饭饱菰蒲，醍醐酣足，雪山开士。","喜银河写照，机边织女，正牵牛会。"]},{"t":"西江月 寿崔伯樾","f":"古风","c":["小病延年药妙，养花天气阴轻。","论诗评画一灯青。","鹤立风怜癯影。","绣口才如轴锦，寸金心似壶冰。","天留漳砚伴行縢。","梓设春浓珠莹。"]},{"t":"烛影摇红 寿陈柱尊，时柱尊在沪","f":"古风","c":["满地江湖，閒情尚寄吴淞棹。","诗清还浥惠山泉，蜡屐梁溪到。","风月秋高岸晓。","抱花眠、瞢腾藉草。","羲皇入梦，酒国无愁，愁怀知少。","山水因缘，茂陵吟席婵娟照。","故园松菊未归看，暂恋江南好。","儿女灯前喜笑。","乐团圞、凤笙绵邈。","登高期近，萸盏长春，纤葱整帽。"]},{"t":"鹧鸪天 清明日为生圹播树橦","f":"古风","c":["又是清明第一天。","落花时节绿阴村。","农经种树须寒食，莫笑州官报万千。","翻黑坏，点苍烟。","未经移石与疏泉。","东门树槚非吾望，拱木藏魂有赋传。"]},{"t":"八声甘州","f":"古风","c":["岂词人、例选玉楼材，相随作飞仙。","料江湖满地，河山夕照，倦眼慵看。","流水落花春去，天上胜人间。","死遂依刘愿，何羡生还。","风月每思元度，读景阳题壁，赓和都难。","喜殷勤杯酒，相对鬟毛斑。","忽惊传、马塍芳讯，梅谢后、春老半樱残。","焚余稿，饮耆卿井，沁齿清寒。"]},{"t":"宴清都 客枕羁愁，枯灯煮梦，郁伊善感，何以为怀。和草窗登霅川韵，不自知所言之何似也","f":"古风","c":["墙倚秋千倦。","斜阳下、无端心事凌乱。","莺痴绿老，鹃哀红谢，韶华逾半。","生憎欺鬓东风，青蔓染、霜丝吝换。","问连朝、饾饤阴晴，珍劝加衣谁管。","算来春色无多，三分有二，归期非远。","系春不住，柳梢眉蹙，芍围腰减。","纵教赶上江南，已孤负、探芳手眼。","更何堪、引逗情丝，飞霙弄晚。"]},{"t":"永遇乐 寒食","f":"古风","c":["去后之推，今年断火，番数逢几。","数十人生，二分春色，岂等閒红紫。","裁衣刀尺，卖饧箫管，天气薄绵消未。","认桥西、青芜一片，踏处凤靴挑荠。","酒炉茶灶，烟沈帘卷，疑是臣门如水。","鞠蹴惊莺，鞦韆过鸟，人影桐阴地。","赠兰斗草，燖盟温语，怕冷伤春余泪。","百五日、饶剩花风，漫愁婪尾。"]},{"t":"泛春苕·题冼玉清女士水仙图","f":"古风","c":["翠带珠缨。","向游仙队里，恍遇云英。","镂冰质，凌波步，家何在、渺矣蓬瀛。","擎盘独出衣裳冷，弹葱指、顿现娉婷。","商周垒洗，种白玉莹然，心迹双清。","娇颦烟媚书檠。","似冰壶濯魄，一片虚明。","空擎盏，忘沽酒，出门笑、依旧江横。","岭梅兄姊山矾婢，人独立、茜影亭亭。","归魂洛浦，扶醉梦依稀，月可中庭。"]},{"t":"二郎神 和徐伸","f":"古风","c":["月阶閒立，又惹得、满身花影。","奈孤枕遥更，薰炉残烬，凄绝关山梦冷。","望末红楼天边远，外讳说、相思成病。","况狂絮封帘，飞花上鬓，也羞窥镜。","谁省。","鲛珠泪重，鸳衾冰凝。","最苦是宵来，痴成悲极，还待黄鹂唤醒。","油壁轮埋，鞦韆架拆，空负阳春烟景。","要领略、镇日空山太古，成林风静。"]},{"t":"南浦 庚辰生朝","f":"古风","c":["晴意袅游丝，过清明、年光寄在杨柳。","欺鬓恼东风，工薰染、惟许绿波痕透。","无言抚镜，惜花岂为相思瘦。","爇香永昼。","空閒却游鞭，黄莺知否。","消磨投老情怀，似信水漂花，倦云出岫。","无病即閒身，浑忘了、饤饾雨晴时候。","零篇断阕，低吟多在迟眠后。","从今屈指，消几曲春词，几杯春酒。"]},{"t":"望湘人 题张哕丹女弟自绘芍药图，和贺方回","f":"古风","c":["际擎盘捧出，照烛烧余，美人醒醉刚半。","盛露渲颜，殿春婪尾，尚觉寻芳非晚。","舞罢西施，延来娇客，连天晴暖。","记移从上苑，说到将离，苦忆荼薇良伴。","勿谓愁肠欲断。","拟采兰同赠，伤高怀远。","尽一幅生绡，绘出红情深浅。","衣裳想倚，沈香亭畔。","易误玄都仙观，今学得、道服黄装，免被沾泥衔燕。"]},{"t":"南柯子 赠简琴斋","f":"古风","c":["铁壁能抗鼎，银钩善画沙。","崖崩石坠木槎枒。","摹入青田珉玉是专家。","绕帐钗光耀，临池墨气华。","隶芝章草簇云霞。","说到索钟真髓粲天花。"]},{"t":"水龙吟 香江送春","f":"古风","c":["春归等是无家，缘何蓦背蛮荒去。","杜鹃字字，酴醾草草，都成别意。","泪浥残红，赠攀嫩绿，蝶蜂知苦。","更水波南浦，开帆顷刻，催几度，黄昏鼓。","漫说留春有句。","尽吟诗、落花谁主。","天涯游子，销魂依黯，临歧飞絮。","客路非遥，明年预约，江南同住。","奈沈沈海气，楼头杯酒，对斜阳树。"]},{"t":"满庭芳 青山寻杯渡遗迹","f":"古风","c":["我佛尘空，神仙羽化，何曾留迹人间。","空教寻觅，杖履费跻攀。","为爱青青山色，况入胜、古木禅关。","杯盘后，斜阳待渡，苍翠殿吟鞭。","前贤。","西归事，莲花藉足，草屦承肩。","竟携蠡测海，步乱波烟。","杖锡蓬团何处，凭谁问、洞口呼猿。","神鱼蜕，石因望化，杯影待东还。"]},{"t":"夏初临 本意，和洪咨夔","f":"古风","c":["林啭山莺，秧分木马，锦城又浣溪花。","白袷归来，上梁换取鲛纱。","奇峰云景谽谺。","似笺红、绮散余霞。","迎人众绿，涧蒲剑短，陇麦旗斜。","登厨樱笋，出箧蒲葵，霜皮剥果，雪乳烹茶。","瑶琴一曲，薰风知己钟牙。","送客琵琶。","竹芦生、重感年华。","怨无端、饯春迎夏，忙到山家。"]},{"t":"剪牡丹 题江霞公海天飞絮图","f":"古风","c":["懵懂疑云，冥濛胜雪，扰乱一天晴色。","勿笑东风，弄春光无力。","苍茫独立哦诗，江城五月，落梅不假吹笛。","海上成连，有鹭鸥相识。","打头天地都窄。","御寇风、九垓鹏翮。","踪迹怕沾泥，谢绝浪飞，关山南北。","与人竞路悔畴昔。","纵化池萍，空作可怜碧。","鸦墨。","任万千结阵，相忘皂白。"]},{"t":"少年游 宫词，拟小山","f":"古风","c":["霓裳腰舞簇云罗。","丝柳织莺梭。","一片毡毹，钗摇钿坠，落比花多。","有时太液恩波共，春宴付銮坡。","昭阳天外，广寒宵半，缥缈闻歌。"]},{"t":"四字令 拟花间","f":"古风","c":["衣莺染黄。","丸螺谱妆。","垂纱痴欲留香。","指尖儿印窗。","狂花满床。","苍葭一方。","悔教献赋长杨。","掠抛家髻忙。"]},{"t":"西江月 延祥观拒霜，和稼轩","f":"古风","c":["豪客周遭绣幕，诗仙坐拥花城。","异乡偏有故乡春。","织出九张机锦。","蜀帐浓渲霞彩，涛笺艳篆烟青。","西施半醉倚银屏。","临水残脂点镜。"]},{"t":"醉落魄 拟二隐","f":"古风","c":["虚房胆怯。","流苏薰透还慵揭。","风阶拜月吹裙褶。","寄去荼薇，知否侬亲折。","辽西梦境莺能说。","迷离柳絮漫天雪。","归来燕子人离别。","形影相随，羞对过墙蝶。"]},{"t":"菩萨蛮 咏南洋果品十阕 其一","f":"古风","c":["累累大树将军印。","悬腰传到征南信。","捧出钿螺盘。","满堂宾主欢。","蛟腥兼鲍臭。","鼻掩西施走。","闻得木樨香。","回帆人倚装。"]},{"t":"菩萨蛮 咏南洋果品十阕 其二","f":"古风","c":["遥从琛赆梯航至。","腰模掌样香流齿。","游子病风流。","生防黄熟愁。","贪馋难嚼核。","捣碎还成蜜。","甜里着咸酸。","酱园丹返魂。"]},{"t":"菩萨蛮 咏南洋果品十阕 其三","f":"古风","c":["林间鞠蹴蛮兵戏。","球抛木末从高坠。","猴子惯偷桃。","无梯缘树梢。","头颅坚似铁。","髓露肌肤雪。","珍重海南杯。","还须象箸陪。"]},{"t":"菩萨蛮 咏南洋果品十阕 其四","f":"古风","c":["岩冰壑雪中藏腹。","琅玕个个森如束。","素手擘莲房。","云英擎玉浆。","相如消渴病。","泉水新调茗。","肺腑挹清明。","何须山笋羹。"]},{"t":"菩萨蛮 咏南洋果品十阕 其五","f":"古风","c":["沾唇点点胭脂影。","红潮上颊朝酲醒。","颗颗是相思。","羞拈连理枝。","戏郎绒唾面。","汁溅桃花扇。","呕出尽丹心。","思君同海深。"]},{"t":"菩萨蛮 咏南洋果品十阕 其六","f":"古风","c":["新年遗礼衣盛■。","一根一叶相樛结。","烂额谢邻家。","阿香行雨车。","薰人还似醉。","壶唾餐霞渍。","张口血盆开。","蛮酋进宝来。"]},{"t":"菩萨蛮 咏南洋果品十阕 其七","f":"古风","c":["玉龙战败鳞遗地。","避兵藕孔人连理。","西子束纤腰。","面瘢无獭消。","归心望万里。","落土生根似。","枉事说相思。","逢人羞道伊。"]},{"t":"菩萨蛮 咏南洋果品十阕 其八","f":"古风","c":["天孙绣罢抛余铁。","生成佛手招山月。","上鬓玉纤扶。","青黄云一梳。","人生虽梦鹿。","穿鼻工须熟。","指巧乞针灵。","粗防如汝形。"]},{"t":"菩萨蛮 咏南洋果品十阕 其九","f":"古风","c":["风波莫谓人心险。","当前披揭同肝胆。","捧出使君知。","银刀中剖时。","枝头新结果。","甘苦猜由我。","无计识君心。","思侬何许深。"]},{"t":"菩萨蛮 咏南洋果品十阕 其十","f":"古风","c":["挥椎博浪当筵舞。","盐调冰浴初登俎。","蛇毒试先探。","镶银宜髻簪。","扶胥江口庙。","望断西归棹。","到岸诵心经。","如尝禅味清。"]},{"t":"剑器近 和六禾夏日龙湾寓斋雅集，用原韵","f":"古风","c":["乍苔润。","便客展、双双痕印。","榜门树阴添晕。","蛎墙粉。","算游俊。","总胜却、青郊结轸。","河流外，环篱槿。","际天尽。","随分。","一生分仕隐。","江村舒啸句短长，野味饶蔬笋。","雄谈不惜语惊人，任临觞当歌，老饕狂鼓馋吻。","菊花蓬鬓。","杜甫高吟，共感年华别韵。","不辞白雪招秋蚓。"]},{"t":"寿楼春 昙花","f":"古风","c":["思千年灵椿。","比乾坤不老，犹是晨昏。","说甚秋蛄昏菌，寿殇云云。","修短数，天人分。","卅六宫、生机长春。","纵一例华鬘，人间梦断，天上算无垠。","须弥顶，谁移根。","自长辞佛土，偶谪凡尘。","涤荡杨枝瓶水，沐汤兰芬。","开顷刻，娱心魂。","鼻观禅、木樨香闻。","似薝卜林中，蒲团定身衣上云。"]},{"t":"夏日宴黉堂·拙园观荷，余以入山未赴","f":"古风","c":["晚霞明。","看霓裳影艳，虹槛波清。","伊人宛在，似流盼含情。","污泥不染珊瑚骨，步凌波、玉佩无声。","怕红衣太薄，风寒水榭，月落池亭。","不语尽销凝。","似汤薰蕙液，人在蓉城。","西池共被，感沈寂鼍更。","争传并蒂仍孤立，盖高擎、成就鸳盟。","羡几生修到，怜香有分，餐秀曾经。"]},{"t":"夏初临 酬詹祝南题集之作，和原韵","f":"古风","c":["试锦锋摧，生花毫秃，凭阑把剑空看。","一角蜗庐，壶中自觉天宽。","况教峰抱沙盘，敞岩扉、凹隐螺鬟。","资何娱老，阳春白雪，流水高山。","酒徒星散，绮语沤盟，蛮春岁换，瘴海潮还。","无聊生遣，洪炉独铸疏顽。","青鸟衔笺。","俾调和、砌蚓岩猿。","洗儒酸。","詹尹非遥，伫乞箴言。"]},{"t":"浪淘沙 拜李后主生日","f":"古风","c":["生死两同辰。","故国归魂。","珠阑玉砌可怜春。","欲向词仙私乞巧，瓜果筵陈。","天地一吟身。","惭对宫嫔。","围城半阕泪留痕。","七夕笙歌欢顷刻，终算君恩。"]},{"t":"角招 读时贤天成寺禾雀花诸作，恨胜游之不可骤致也。谱此以当卧游","f":"古风","c":["雪绡薄。","天孙巧、碎裁千万冰萼。","上林无分托。","识向暖飞，纥干冻雀。","花讯昨凭，点破公坑寥邈。","饮啄天然辽廓。","争粮鸡鹜休猜，愿老依林壑。","搜索。","众芳谱略。","牟尼一串，白蝠联腰脚。","湿云春漠漠。","守定寒香，栖枝梅鹤。","移根计错。","傍净宇、招提兰若。","远想哀鸿京洛。","稻粱计，望禾花，饥肠涸。"]},{"t":"花犯 初秋山中始见红叶，和碧山","f":"古风","c":["影娟娟，斜阳古道，红尘逐流水。","故乡百里。","自病叶辞柯，同入秋思。","塞鸿未到情难寄。","天涯亭独倚。","记艳迹、御沟题句，醒来原梦里。","何须妆点买脂胭，斑斓似郑佩，江皋同委。","妃子靥，初中酒、不关憔悴。","催诗料、檐花伴落，飘几片、敲门人欲起。","偶晓醉，篱边卧处，偎身疑锦被。"]},{"t":"虞美人 庚辰中秋","f":"古风","c":["青天碧海连年恨。","无晕仍风信。","娇痴儿女说团圆。","试问团圆骨肉几尊前。","嫦娥妆罢轻云蔽。","欲出踌躇费。","缑山仙客爱光清。","又怕琼楼玉宇太分明。"]},{"t":"十月桃 本意，和张元干","f":"古风","c":["江绡湘缬，有佳人障袖，初试新寒。","醉倚霜篱，粉渍误认霞丹。","莫是天台话别，腮泪洗、冷雨潸潸。","仙源避世，怎贺秦正，犹拜风鬟。","问陶潜、去后林园，菊径寻芳，几许阑珊。","路入元都，春风人面依然。","谁教媵梅根叶，江渡早、潮湿衣斑。","天鸡一唱，梦醒刘郎，暖酒炉残。"]},{"t":"沁园春 和霞盦赴会夜归闻警之作。时山居畏寒，未赴","f":"古风","c":["局促吟壶，屏却声闻，别是一天。","念离巢鸥鹭，逢场杯酒，飞空欠舄，问渡无船。","惨澹风云，抢攘岁月，警讯犹惊呜咽传。","桑乡事，叹寒梅园菊，萎落荒烟。","鞭先。","归思鸿边。","计琴剑、谁家能瓦全。","算戏钩藏座，新欢枕飞，觞唱月邮，笺筒递险韵珠穿。","梅鹤凄清，桐鼍哽咽，醒我骚魂梢月纤。","吟肩耸，忘去閒身滞，在异域山川。"]},{"t":"乌夜啼","f":"古风","c":["秋风吹雁横天。","写云笺。","总有无穷心事对江山。","关塞黑。","程难息。","羽毛单。","多少愁人为汝倚阑干。"]},{"t":"乌夜啼","f":"古风","c":["高楼响沸笙歌。","舞婆娑。","莫问当头星斗夜如何。","钟漏尽。","薰炉烬。","露珠多。","无奈追随残烛簇飞蛾。"]},{"t":"乌夜啼","f":"古风","c":["瑶池王母筵开。","竹歌哀。","见说人间八骏复西来。","仙路辔。","尧阶羽。","早安排。","赢得漫天蜃气幻楼台。"]},{"t":"乌夜啼","f":"古风","c":["宵寒湘瑟泠泠。","倩谁听。","偏有鱼龙秋醒眼垂青。","山月洁。","天风瞥。","大江横。","丫髻仙童游戏正骑鲸。"]},{"t":"过秦楼 和慈博","f":"古风","c":["露重帘僵，炭熸灰死，盼极南天鸿断。","桃根渡楫，花絮年梭，倦理当年歌扇。","空悔陌柳楼头，赚我封侯，定山三箭。","自骊歌唱后，长安春近，玉关人远。","今拟寄、无限相思，机中锦字，血泪相和红染。","夫山石化，妾井波沈，生怕君心中变。","空有青菱照愁，张谱虽传，谁摹眉倩。","算阑干倚遍，犹剩西谯漏点。"]},{"t":"迷仙引","f":"古风","c":["霜天霁。","冻阁茶烟，萦帘丝细。","粉剩脂残人乍起。","增娇媚。","剪尺摩挲，怕宿酲还醉。","思远道，阑干倚。","鱼渺雁绝，懒对青铜照，从鬟委。","冷清清地。","乌东上，蟾西下，年华且漫夸秾李。","北塞枉凝睇。","屏山隔，灯花翠。","来去无踪，夜夜思潮洞庭水。","书写罢，谁为寄。","费怀人、几点登高泪。","山如洗。","幸寒林、早落秋声里。","教侬心、平地驰千里。"]},{"t":"万年欢 十一月十六日祝黄梅伯先生生朝，和六禾。六禾用晁无咎体，少一韵，今从词律补之","f":"古风","c":["如鲫名流，数诸贤过江，谁最枭采。","耐冷头陀，曾饰出场冠佩。","修到罗浮玉骨，忍更效、阎浮时态。","鼓暇滕阁吟秋，笔花常蘸烟霭。","一瓣心香下拜。","想聪明冰雪，胸襟湖海。","裙屐风流，梅栋诗名长在。","千顷清陂沾溉。","记握管、曾窥天外。","今纵说、香火因缘，种根萍梗何碍。"]},{"t":"丑奴儿慢 和慈博咏雪，和梦窗之作","f":"古风","c":["灯摇眼缬，珠缀檐花圆影。","围炉觅、禅心诗思，冰玉双清。","瑟缩吟肩，寂寥短发一梳明。","翠禽招我，罗浮梦境，鹤氅身轻。","准备玉壶，沽春灞岸，休俟霜晴。","似悬拟、故人心素，尘洗红情。","摩诘林峦，粉痕弹隙露鬟青。","吟壶薰鸭，室生虚白，镜澈层层。"]},{"t":"楚宫春慢 六禾步草窗韵咏霜，改首韵为日字，疑必有据，从之","f":"古风","c":["西崦暮日，扇蔌蔌威棱，万花蔫谷。","冻瓦篆，鸳衾抱，余寒眠足。","塞雁初来，冷讯报、蒹葭江国。","变乱阴晴，讵蛮荒、燕狱同冤，坐看朱夏凋绿。","鹰隼风尘遍地，明月夜、呜咽啼乌遗曲。","葛屦沽春，赏雨输他茅屋。","玉杵云英烂捣，蓝桥路、何缘借宿。","错讶东君，孕冷中、胎结梅花，缕缕梢头悬玉。"]},{"t":"永遇乐","f":"古风","c":["蜗蛰庐寒，禽啁山晓，霜迎菊序。","邓尉前尘，罗浮冷梦，似尧年鹤语。","征裘凋敝，奚囊掇拾，剩得鬓霜几缕。","骚心续、吟逋赋璟，砚蘸玉泉金露。","香中誓住。","教花长恼，枉责约期轻误。","月白昏黄，风梭雨线，心在孤山路。","疏泉傍竹，携锄亲种，拟补巡檐千度。","君休问、故乡信息，绮窗着处。"]},{"t":"合欢带","f":"古风","c":["兜罗绵手摩空。","橘千树，佛香浓。","讵比东陵消夏品，玉葱分、渴润诗咙。","何烦指月，祇凭抱瓮，得豆功同。","谷回温、莲花双合，禅机嫌露天龙。","田家棚底话秋风。","散天花、远蹠高踪。","见说宣和徵故实，道山筵、屈数雍容。","胡卢漫诮，智珠在握，偈市其中。","抵谈深、阿丰饶舌，瓞绵传法种无穷。"]},{"t":"穆护砂 和霞盦香江除夕","f":"古风","c":["岁暮峥嵘矣。","卧南陬、试活南事。","响洋场爆竹，轰雷飞电，落花蔫红殷地。","幻海市、珠光连十里。","斗百货、阗衢充肆。","朵论价、牡丹金换，笑任索、桃花门倚。","筵敞藏钩，山薰沈水。","寓公巨贾闹朱扉。","又连场博簺，欢呼竟夕，依旧洛阳似。","悬隔壤宵尺咫。","怨蛮春、渡江无翅。","酌一杯婪尾，壶沽无路，雨渍茅龙犹是。","幸尚有、炉灰书问字。","算更演、祭诗余技。","书檠仄短，照遗虚耗铜币绌。","买剩呆痴，孤影孤单，阿奢无分，辛盘料理。","玉纤非计，空山旧雨谁来，东风明日至。"]},{"t":"天仙子 和六禾腊月望夜微雨韵","f":"古风","c":["答答羞人娇面躲。","妆促嫦娥吟烛堕。","团圆话别尽今年，脂粉涴。","蓝桥锁。","罅透巫云神女唾。","碎渗麴尘花絮过。","城远山深无倡和。","纵教春意上梅梢，居僻左。","寒无那。","半破蒲团朝壁坐。"]},{"t":"临江仙 元旦，用冯延巳体","f":"古风","c":["晓钟催送蛮春到，桃符椒颂都新。","东风欺负白头人。","贺无庭雀，排闼尽痴云。","休疑爆竹驱山鬼，宵来红叶堆门。","肩寒吻渴瓮生尘。","茶烟炉篆，斗室自氤氲。"]},{"t":"一剪梅 拈题得壁苔，用清真体","f":"古风","c":["削立危崖似怯寒。","文绣层层，包裹婵娟。","洞天开处舞飞鸾。","横掠萝屏，韡印弓蛮。","愁锁春宫十二阑。","别矣王孙，黯色年年。","题情欲倚惜葱芊。","呵问天心，绿晕成圆。"]},{"t":"蕊珠间·印泥，为陆医生作","f":"古风","c":["朵云心笺，霞尾露泫。","芝英红茜。","想前身，在珠宫，捣霜同炼。","辰砂曾碾。","甲葱尖溅。","唾绒口脂分艳。","定磁伴。","考槃余事待选。","油沁冰纹鬃眼。","水银金玺，恍惚元封曾见。","口珰缄腻，肌丝茸软。","教看寸丹深浅。"]},{"t":"燕归梁 题作甫息茶庵图卷","f":"古风","c":["蝉噪庭槐绿已浓。","归燕帘栊。","蜗庐息影四山中。","茶烟漾，藕花风。","缣缃插架签标帙，城环拥，拟侯封。","别饶心事问残红。","寒衾梦，一声钟。"]},{"t":"锦缠道 题冼玉清教授海天踯躅图，图绘杜鹃","f":"古风","c":["照水明霞，薰染暮山初透。","杜鹃啼血流丹咮。","谁栽南国调鹦豆。","误认红桑，浅到沧瀛后。","向郊原讨春，春醲如酒。","泪盈盈、紫殷离袖。","正路歧、踯躅斜阳候。","甘泉火通，见说蕃胡狩。"]},{"t":"摸鱼儿 题陈炳权校长万里封侯图","f":"古风","c":["好男儿、峥嵘头角。","何甘窗下枯槁。","横腰三尺青蛇剑，风雨欲来狂啸。","吟未了。","起健者班生，商略从戎好。","长门官道。","是万里初程，一鞭先路，忍恋栈边草。","西陲事，天末狼烽正照。","将军度幕征剿。","燕然麟阁真机会，休负锦旌牙纛。","君莫笑。","王尊驭、俳佪陇坂供凭眺。","沿边荡扫。","须脚踢黄龙，腰悬金印，尚及人年少。"]},{"t":"探春慢 百花生日","f":"古风","c":["草甲苏烟，花辰醉露，中和夹钟律转。","荠傍墙挑，蘋生水活，触处探芳心眼。","春过三分几，试数遍、曲江游宴。","送来百舌，繁声一片，觥堂歌管。","贺客园林莺燕。","正锦缀竿高，门悬弧遍。","藤褓交盛，苔钱工数，天姥洗儿年惯。","计筵开弥月，喜春饯、归期尚缓。","珍嘱封姨，护犀帏，漫轻卷。"]},{"t":"水龙吟 港地避难室四郊棋布，诚危急中一保障安全壁垒也，宜有以落之","f":"古风","c":["魔王弃甲天衢，藕丝孔是容身地。","舟藏壑邃，户封泥固，究缘何事。","报到天花散，沾衣怕、尘心消未。","计阿香宵驾，冰天雪雹，连环解，防游戏。","矮屋风檐滋味。","箔蚕眠、晓钟催起。","文场战罢，兵间劫始，惊魂余几。","广厦千间在，何曾见、颜欢寒士。","笑相逢隧道，融融泄泄，算平安字。"]},{"t":"翠楼吟 吊崔伯樾","f":"古风","c":["雨泣林容，寒凄柳骨，骑鲸故人长往。","丹霞吟草在，侍笔砚、珠光生掌。","逸情云上。","尽谢屐幽穷，戴舟兴访。","凫飞雨、山灵遗恨，待题延项。","撰杖山易青黄，忽词仙骑鹤，辽天长望。","联床风雨夜，商量密、今成绝响。","蛮乡经帐。","记接席晨昏，前盟息壤。","空惆怅、溪藤如故，挽歌悲唱。"]},{"t":"凤箫吟 和霞庵閒行宝云道中遇雨作。春雨连旬，人方闭户高眠，我独冲寒卖技，不独翘首宝云，如在天上已也","f":"古风","c":["坠檐花、衾寒瓦响，幽人正好偷閒。","三杯酣卯酒，茶烟词卷，迭篆碧研丹。","街头人踯躅，落钟后、一饭都难。","方蹑席抠衣，满身清露斓斑。","绵蛮。","莺喉乾涸，天教腔润，箫市歌残。","耸吟肩瑟缩，还怯衣单。","唱莲花落罢，天浆洗、乞钵涎馋。","堪自慰，明朝他顾，诗社墦间。"]},{"t":"一寸金 花影，和六禾","f":"古风","c":["春色分明，为怎糊模遽如许。","透帘栊宵月，晴波摇荡，阑干朝旭，娇容摹取。","睡起婆娑舞。","绣茵卧、钿钗衬步。","似离魂、倩女迷踪，惆怅无情暴风雨。","幸傍灯檠，归来环佩，鸿都帐中遇。","似水仙留袜，春泉赐浴，宫妃理镜，晨妆回顾。","铅墨渲缣素。","疑笼罩、恨烟怨雾。","终须见、铲迹人间，蜂蝶无觅处。"]},{"t":"卜算子慢","f":"古风","c":["岩藤罥户，墙荔曳风，别是一番疏翠。","閒话僧寮，冷落灶烟天气。","仗金刚、护梦悽惶里。","写不尽、旧愁新恨，朝潮夕汐相继。","海啸淹闾里。","况旅鹤惊霜，倦鳞喁水。","笙路东风，日暖辜他月二。","困山梁、饮啄无欢意。","祇绕树、旁皇三匝，问枝栖焉寄。"]},{"t":"绛都春 为吴亮侪题木棉图","f":"古风","c":["天花四散。","似火簇骊珠，烧空璀灿。","沸耳鹧鸪，三月风光蛮春晚。","交龙衔烛冲霄半。","更旁缀、鳌灯千万。","越王台下，餐霞吸露，送寒迎暖。","又见。","波罗古庙，临巨澥、撩起蛰虬宵战。","标夺赤城，甲楮云绵烟丝乱。","庭燎高举诸仙宴。","酌手盏、琼浆酬劝。","侑觞绛树，双声莺簧调转。"]},{"t":"永遇乐 上巳，和慈博","f":"古风","c":["未到春归，且从春乐，乐游游宴。","修禊人来，流觞水曲，更沸天弦管。","桃花汛后，华林园外，那有等閒莺燕。","落蛮荒、绮罗裙屐，年少升平俱远。","江湖满地，清明作客，身共时光流转。","琴谱南风，筵开东洛，盛会无缘见。","衰颜白发，排愁无力，空负采兰心眼。","稽故事、金人捧剑，霸图待展。"]},{"t":"陌上花","f":"古风","c":["鸳鸯谱牒，前生谁注，水萍同幻。","月老欺人，枉说赤绳双绊。","谈恩讲爱痴儿女，夫婿黄金心羡。","算鹣鹣鲽鲽，到头缘尽，漆胶终断。","旧时王谢宅燕。","移垒去、本是司空见惯。","试看黄台瓜实，累累珠串。","馋夫一摘供消渴，抱蔓讴歌归缓。","怕春深槛外，鹦笼无锁，雉媒偷眼。"]},{"t":"珍珠帘·辛巳生朝","f":"古风","c":["飞鸿瞥影回头渺。","堪惆怅、两事升平年少。","春色半阑珊，况影形相吊。","面目须眉无一是，更剩得、无聊怀抱。","壶小。","对茶烟禅榻，契结昏晓。","偶尔裙屐追随，借词牌杯酒，涂雕枯槁。","问字半亭，虚守太元残草。","海澨红桑经怕看，敢醉心、安期仙枣。","休笑。","任老去文园，人求遗稿。"]},{"t":"西江月 咏霞","f":"古风","c":["万丈赤城标建，九张文锦机连。","天何此醉且醺然。","瘴海红潮上面。","散绮空花四照，飞丹江草逾鲜。","黄昏好景写云笺。","人在夕阳庭院。"]},{"t":"新荷叶 本意，和慈博","f":"古风","c":["抛种横塘，休愁消息都无。","南岸红衣，宵来梦境糊模。","玉人纤指，擘春潮、戏动行鱼。","东风才放，数疑姹女青蚨。","哥绿盘盂。","雨来初试跳珠。","鸳宿龟游，漫教翠盖周扶。","田田模样，拟崔徽、娇面何如。","小家碧玉，凌波学步纡徐。"]},{"t":"夏云峰 和六禾宝云道中日光浴之作","f":"古风","c":["爇兰汤。","薰沐赋、湘累绣口骚肠。","又似水嬉拭垢，凫没鱼翔。","濯从江汉，都输与、曝向秋阳。","旷莽界、眠红藉绿，颠倒衣裳。","登高不羡招凉。","讵犹恋、夏云恶木阴长。","正好背偎棉纩，腹晒书囊。","精华嘘吸，通沆瀣、气辨青黄。","忍忘却、锄禾日午，珠酣淋浪。"]},{"t":"虞美人 题陈炳权校长十分春色图。图作折枝花十色","f":"古风","c":["瑶台群玉诸仙子。","异地同时至。","楼罗新历广题名。","不论燕肥环瘦总娉婷。","荒斋难得花消遣。","聊写崔徽面。","低头合十祝东君。","许我众香国里结芳邻。"]},{"t":"玲珑玉 新笋，和慈博","f":"古风","c":["鸾翥龙吟，甚时听、暮雨潇潇。","惊雷出地，一旬便已干霄。","似此峥嵘气象，■文章才露，头角龄髫。","今朝。","绷婴孙、犹系锦绦。","料得樱筵待伴，证禅心玉版，风味江瑶。","数旧添新，又何望、扫叶煨烧。","休论薛滕谁长，且留证、山香竹讯，佛影蔬苗。","笑馋守，渭川胸，千亩未消。"]},{"t":"留客住 港中开发大屿山，亦岛国中一拓地法也","f":"古风","c":["国蜗角。","计一朝、舞人旋袖，楚南天窄，凿空骞槎西域。","山移泰岱平处，海塞蓬瀛，浅后终计错。","轮台故事，议屯田、汉代尚留边略。","移民约。","脱剑牵牛，操弓徙鳄。","井里桑麻，警枕无虞闻柝。","传说桃源避世，葛老移家，驱丛罗众雀。","僧归寄语沃洲山，莫认护舟深壑。"]},{"t":"荔枝香近 荔支，用七十三字体","f":"古风","c":["岭南红云，故事汉宫宴。","海岛蛟窟筵席，虬珠琼娘解。","卸罗襦、玉体横陈温暖。","途远。","尘骑何劳盼断。","我生馋魔，病渴徒艳羡。","遇汝他乡，唇润处，色香变。","东坡百颗，选树论园总虚愿。","小年何况今见。"]},{"t":"齐天乐 帆影","f":"古风","c":["五湖烟水苍茫里，飞来楚云一片。","澹处还浓，斜边陡正，几幅蒲葵余半。","春波素练。","值日落收蓬，墨痕描懒。","讯息模糊，布帆无恙载来远。","重水重山万里，尽侬情郎楫，形影相伴。","南浦君归，东风潮涨，尽入怀人心眼。","芦汀蓼岸。","正次第经过，分阴都遍。","雨黯渔村，寻踪惊梦幻。"]},{"t":"湘江静 竞渡","f":"古风","c":["白浪飞花雷叠鼓。","怎匆匆、冒烟冲去。","拿舟独出，齐桡着力，赌锦标争取。","青眼到红妆，东西岸、凭栏延伫。","楼船下濑，鸳鸯弄潮，欢声里，忘昏暮。","奈汨罗，人正苦。","况重渊、老魔盘互。","褰裳赴救，赖后先邪许。","入水斩蛟龙，江心剑、待清波路。","沈沈楚魄，万方多难，大招谁赋。"]},{"t":"一寸金 和六禾书感，用梦窗韵","f":"古风","c":["哨骑无才，敌人偏传赵王猎。","忽毒鲸波撼，关沦碣石，洪蛟潦发，灶沈都邑。","徵调纷符牒，狼烟里、鹤猿并泣。","长江域、天堑填平，似水银倾孔都入。","踞地开场，喽啰呐喊，陈书发苏箧。","幸上攀星斗，云生秋驾，湛沾雨露，门标春帖。","风阻瀛洲楫，西江水、倒流建业。","君知否、傍树狐狸，落防霜后叶。"]},{"t":"百字令 自题七十五岁小像","f":"古风","c":["头颅如此，幸本来面目，差能依旧。","故我今吾形问影，媚骨几时消透。","客路栖皇，僧邻拣买，猿鹤窥空臼。","江湖满地，水乡仍傍云岫。","有涯生遣何凭，庄严七宝，倾倒修楼手。","举似苏辛羌柳派，鱼掌两难兼有。","梦境迷离，神山缥缈，风受来舟否。","碧窗凌乱，夕阳红恋衰草。"]},{"t":"锦堂春 东涌道中得牛与人争路，田将水作衣句。演之为词","f":"古风","c":["行脚试将筋力，临流愧此眉须。","骅骝争道非吾事，自分老泥涂。","一路烟云染袖，千山苍翠盈裾。","从来误我儒冠在，莫作水田呼。"]},{"t":"河传","f":"古风","c":["无主。","飞絮。","垂杨袅袅，乱撩离绪。","斑骓行后枉回头。","悠悠。","门前沟水流。","今年秋草明年绿。","河曲。","绿到王孙足。","到伊时。","料伊知。","归期。","忍何心再迟。"]},{"t":"少年游 姜花，和慈博","f":"古风","c":["葛蒲花老，薰风惯见，暖御熟梅天。","紫未根蟠，白先拳绽，葱指擘丝烟。","虚传桂性同辛辣，面目春妍。","攒玉蚕丛，剪纨蝶板，霜影蹙鳞圆。"]},{"t":"桃源忆故人 茉莉串，和霞盦","f":"古风","c":["素馨十亩花田雨。","消剩汉宫浓暑。","小小南强衔署。","香满楼罗薄。","一团温馥薰钗股。","次第芳心环吐。","帐护残妆縠雾。","悦魂魂没主。"]},{"t":"采绿吟 和六禾水阁追凉，观江中渔火作","f":"古风","c":["钓罢红衣岸，正人在，麝亭东。","盘冰雪藕，笛风凄柳，霜月当枫。","鱼榔韵响波微动，白鸥四散无踪。","引遥眸、星星火，迷离掩映孤篷。","帆落舣蒹葭，村沽醉渔翁。","罢钓篝火，夜色起潜鳞，在水绿灯红。","叹趋炎、投暗为明，华堂烛、焚身等飞虫。","凭栏意、俯仰息机，观云太空。"]},{"t":"惜红衣","f":"古风","c":["点额妆新，偎灯索笑，古欢如昨。","自唱骊歌，怅山河绵邈。","南枝寄我。","慰客路、阳春行脚。","无著。","来日绮窗，负守枝寒鹤。","浔江府幕。","独宿凄清，这番算计错。","罗浮旧事，酒俎梦依约。","何况讨春溪棹，少个美人栖泊。","纵妻梅人去，待我讵无残萼。"]},{"t":"烛影摇红","f":"古风","c":["竿木随身，逢场吾辈原应尔。","有涯生遣靠无聊，焚砚君苗未。","勿笑雕虫小技，计衣冠、何非游戏。","功名屠狗，扪虱经纶，遭逢交臂。","傀儡牵丝，幕中啼笑欺人事。","扶轮负轭仗长材，引重同蝼蚁。","百步贤无彼此，取题材、依然故纸。","儒冠同误，既虱人间，又垂狐尾。"]},{"t":"玉蝴蝶","f":"古风","c":["人去塔铃无语，禅关草翳，久閟幽光。","倦羽投林，徵歌调不成商、阳幽明、鹫灵降岭，报消息、鸟使窥窗。","思微茫。","追摹杖履，如见羹墙。","回翔。","罗浮仙种，纵非佛国，亦算仙乡。","管秃肠枯，文章借彼衣裳。","漆园梦、深惭变幻，滕阁画、借染丹黄。","墨淋浪。","高僧传在，千古栴香。"]},{"t":"双头莲 和六禾闰荷花生日之作","f":"古风","c":["人面张郎，叹粉坠脂零，与时流转。","红衣隔岸。","占阑暑、弥月薰风无限。","今年赐橘重逢，观莲人健。","莺与燕、试舞徵歌，觞称碧筒庭院。","闻道仙子凌波，尚徘徊太液，人间留恋。","横塘锦段。","比旧样、簇簇云霞炫艳。","相与重护盟鸳，怕菱讴惊散。","知太华、玉井秋寒，褰裳意懒。"]},{"t":"拜星月慢 和霞盦七夕阻闰延期之作","f":"古风","c":["计日关心，隔河同恨，夙驾先期慵整。","故事蓝桥，迟云英来迎。","为人误，见说、观莲旧约寻觅，赐橘层恩荣幸。","累尔双星，站河边支影。","绣针楼、待月劳先凭。","支机石、织锦凭谁赠。","窃笑乞巧欺人，拙工夫长等。","算牛郎、留得钱行聘。","怕桥鹊、怯冷工难竟。","况递误、酒熟萸香，登高逸兴。"]},{"t":"花发沁园春","f":"古风","c":["无意催诗，有尘清路，昏鸦何处投林。","南山殷雷，北谷漏天，十里一色浓阴。","猿饥鹤怨，正撩乱、负米归心。","暝色合、加紧催人。","出云残袅钟音。","若问吾庐何在，指前路莫辨，雾岫烟岑。","痴云壅径，怒溪没石，人疑妆点山深。","侵肌袖湿，似客途、老泪沾襟。","叹好景、有限斜阳，尚悭别我西沈。"]},{"t":"长亭怨慢","f":"古风","c":["荡愁路、海天飞絮。","缥缈蓬莱，西厢扃户。","望里三山，五云深处在何许。","元都栏槛，曾借枕、将枯树。","树叶已辞枝，况落泊、江关逢此。","朝暮。","过红墙外道，蹈遍落花无数。","蘼芜沈讯，约偕隐、青鸾空付。","曾见否、世外团瓢，与猿鹤、相为宾主。","傥梦里逢卿，应诉年时愁缕。"]},{"t":"长亭怨慢·读慈博词，因忆查颠山初掘凿时，主人欲以风雅为商业倡，余亦狗虱戏中演员之一。地既幽旷，酒肴亦丰腆。及声气既开，主人意倦，局以屡变，而竟至于散。今偶到凭眺，古榕虽存，而诸人多物故者，因借题抒感尔","f":"古风","c":["野风聚、落花飞絮。","好个吟壶，幽深庭户。","七步催成，半閒偷得幸天许。","绿阴十亩，凉健我、榕门树。","爪甲若非龙，那得见、蜿蜒如此。","日暮。","瞰洋场灯火，浮出市声无数。","风签月券，喜先荷、东皇支付。","莫误认、蛮海春多，毕竟是、燕莺无主。","试检点、高阳鹤发，几余霜缕。"]},{"t":"新雁过妆楼 和六禾韵，答霞盦山楼听雨作","f":"古风","c":["檐泪汛澜。","添新绿、帘前露立烟鬟。","滕薛争先，不知多少琅玕。","洗梦溪声千尺落，偎人襟暖半床宽。","水云寒。","红鱼白磬，断续更阑。","归山。","吟壶纵小，计催诗剪烛，难得偷閒。","对影成双，灯前未感孤单。","明朝随分俯仰好，弃置鞭梢兼扇纨。","青蓑笠，趁涧痕添涨，准备投竿。"]},{"t":"燕归来，为胡伯孝题黄穆父古鼎山茶图","f":"古风","c":["云在纸，露凝枝。","花盎又蟠螭。","描摹何必买胭脂。","西子古妆时。","印人笔。","天仙魄。","妆就吉金色。","茶余读画漫题词。","秾淡要相宜。"]},{"t":"阮郎归 十月十日海风大作，沈船拔木，农产摧折盖殆尽。急归山察视，吾庐尚存，填此志幸","f":"古风","c":["狂飙驱雨倏东西。","波涛山与齐。","花幡无力任花飞。","山人归梦疑。","蔬圃乱，豆棚欹。","披离双树枝。","秋风茅屋杜陵诗。","抱茅童未欺。"]},{"t":"好女儿 紫罗兰","f":"古风","c":["秋色无端。","渲染衣斑。","漫相疑、剪碎红霞片。","作绫裹束，倩风扶起，半醉颓鬟。","应是春心犹在，閒不了，闭雕阑。","似佳人、薄袖新寒。","怯挹霓裳旧谱，凤城缘满，又落人间。"]},{"t":"诉衷情 和梦窗","f":"古风","c":["人情何事淡于鸥。","零梦醒沧洲。","斜阳点缀残画，总是海天秋。","多少路隔红楼。","月如钩。","团圆何日，别后相思，诉说从头。"]},{"t":"探芳新·和慈博风后新绿沃若，秋气变春之作","f":"古风","c":["洞庭波，正酿寒作霜，万青摇落。","又斗群龙，鳞甲漫天冰雹。","风姨舞娱海若，袖垂云、钿弃陌。","叹生机、摧夷尽，况迫严冬穷剥。","何幸天工点缀，忽病叶苏魂，稚荑茁角。","去矣重归，谁谓阳春无脚。","风尘秋娘暮齿，著春衫、姿绰约。","感山河、嫌破碎，绿天重幂。"]},{"t":"四犯剪梅花 回山息影，闭户理愁。读六禾蓼芦二词，泠然秋色动摇几案间，愈难为怀。爰依韵和之 其一 辘轳金井·芦花","f":"古风","c":["鲤鱼风起。","剪梨云遍地，远弥天际。","弹粉林峦，得王维图意。","澜翻湖底。","愁鱼嚼、与红同碎。","搅透秋心，催来暮境，谁能堪此。","诸天尘劫待洗。","缀枝头朝露，如炫珠泪。","鬓白萧疏，对江关颜悴。","伊人在水。","访生处、蒹葭乡里。","吹絮帘栊，装棉屏障，教人寻味。"]},{"t":"回山息影，闭户理愁。读六禾蓼芦二词，泠然秋色动摇几案间，愈难为怀。爰依韵和之 其二 雪狮儿·蓼花","f":"古风","c":["西风老我。","叹长此、霞浦烟村，浮根飘泊。","水国花疏，早被哀鸿知觉。","西楼被薄。","黯白石、云沈红萼。","芦荻外、枫霜渔火。","阳斜潮落。","簇红原非寂寞。","稻粱谋、处稳信音空托。","茎叶无多，啖尽朝饥犹昨。","重阳待作。","菰米酿、聊共杯杓。","枯丛鹊。","悔与汀鸥为约。"]},{"t":"酒泉子 和六禾词已，余兴未尽，媵以二小词","f":"古风","c":["一磐空山摇古翠。","门掩灯残烟坠穗。","林深猿鹤正眠秋。","络纬织羁愁。","侧身天地苍茫里。","似粟如沤总浮寄。","金筌片玉半成尘。","枉费作词人。"]},{"t":"恋绣衾","f":"古风","c":["今朝无酒算遣愁。","酒多时、防化泪流。","感身世、浮沈事，问前程、波没白鸥。","幽栖莫笑蜗庐小，似苍茫、烟海系舟。","待认定、蓬莱路，借仙人、黄鹤漫游。"]},{"t":"惜红衣 送中央在港考选海军新生飞渝入学，和白石","f":"古风","c":["牢补亡余，牖营暇日。","绸缪心力。","树木十年，桐材挺新碧。","横汾下濑，期有待、昆明池客。","风寂。","蛮海昼眠，让痴龙苏息。","东沟旧陌。","折戟沈沙，猿虫瓦尸藉。","楼船一霎水国。","殉溟北。","屈指拜登君赐，讵等斗星扪历。","要弄潮儿健，优狎近蓬风色。"]},{"t":"惜红衣·和六和辞郑大登高约韵。郑园高不可攀，余亦惮行。登高而怯高，老可知矣","f":"古风","c":["孟帽辞风，陶园涉日。","漫夸筋力。","看菊缘悭，裁筒羡杯碧。","山鸿海燕，同逆旅、光阴为客。","甘寂。","蜗屈一庐，作权时将息。","相逢柳陌。","张绪当年，芳馨竞声藉。","游鞭指路去国。","各南北。","孰惜插萸人老，犹叹劫尘亲历。","■翠微凝望，吟兴比浓茶色。"]},{"t":"惜黄花 和霞盦孩儿菊展重阳作","f":"古风","c":["英餐秋饱。","鬓簪人老。","记青年，韵蹁跹，唱红孩调。","七五度重阳，萸酒长欢笑。","花笑我、汝头童少。","窥篱鬟好。","缀瓶钱小。","面团团，骨绵绵，锦衾绷倒。","休说老来娇，忍忘儿时钓。","奈白首、怕风欺帽。"]},{"t":"醉桃源 剪秋罗","f":"古风","c":["剪秋不断剩烟丝。","丝丝皆上机。","罗裳织就裹虞姬。","凉风吹舞衣。","南越种，汉宫姿。","生来休怨迟。","嬉春姊妹纵分离。","海棠还伴伊。"]},{"t":"殢人娇 秋海棠","f":"古风","c":["谱序春人，悲生秋士。","背时怨、露零悬泪。","断肠人在，南墙冷地。","烧烛照、何曾有相怜计。","性本辛酸，容逾憔悴。","凄风里、罗衣初试。","石家金屋，西川戚里。","谁与供、春阴始终护你。"]},{"t":"三部乐 和霞盦风后木叶枯脱之作","f":"古风","c":["林秃山髡，扫木叶一空，似头新沐。","蛎墙薜荔，凌乱诗人吟屋。","未岁寒、松柏先凋，岂梅花五月，笛声飞玉。","横汾帆乱，又唱大风一曲。","更伤拣枝旅雁，当月昏水阔，冷餐寒宿。","许教垒完檐幕，焰支窗烛。","问尘襟、涤除几斛。","身世泪、真盈一掬。","梁月照色，荒三径、多少余绿。"]},{"t":"泛清波摘遍 中秋前一日集黎墅，继霞盦作，和小山","f":"古风","c":["桐疏燕社，莼老鲈乡，天慰旅愁秋信好。","霓裳仙曲，恨不铙歌共传早。","横门道。","风尘隼出，烽火狼清，都市骆驼东去了。","试问秋霜，甲弃肌寒透多少。","故乡渺。","杯酒借浇烛花，囊锦别添诗草。","闻捷衣裳泪盈，此情难晓。","碧天杳。","明夕管笛唤来，今宵广寒须到。","预唱琼楼水调，任腔颠倒。"]},{"t":"二郎神 饮李氏康乐园展重阳作，用汤恢韵","f":"古风","c":["翠微径仄，怯鬓白、被风飘影。","念橘柚新阴，枌榆旧社，门掩裙裾客冷。","比似侯爪将军树，勿误认、文园秋病。","喜百果缀星，千花扶路，如临天镜。","重省。","衔杯笑语，云浓液凝。","识棨戟门庭，邯郸客枕，先被流莺唤醒。","松菊三休，茱萸再醉，犹是龙山风景。","人解道，檀锁雕笼鹇放，一帘尘静。"]},{"t":"玲珑四犯 和瞿禅","f":"古风","c":["不分閒愁，便闻雁当筵，飘泪盈斝。","胶漆初情，未许教人寻罅。","谣诼见妒无端，枉扫尽、远山眉画。","又争妍、翻新花样，重剪入时裙衩。","藏娇空有閒庭院，浪蜂蝶、莹莹朝夜。","蔷薇变幻春消息，闻道徒惊诧。","不惜买赋费金，难复保、长门声价。","望稿砧、山上高寒，何处问天杯把。"]},{"t":"临江仙 和瞿禅","f":"古风","c":["沦落异乡为异客，茫茫流水长空。","愁闻初雁梦闻钟。","云山权小隐，桑海怕重逢。","此处故乡仍第二，缘何求去匆匆。","凭阑高唱满江红。","青蚊锋斫地，黄鹤翼乘风。"]},{"t":"潇湘逢故人·和六禾夜闻孤雁作","f":"古风","c":["南楼睡起，怜吟魂未稳，步绕行窝。","讵关避张罗。","怅烟雨歧路，木叶微波。","西风半老，为寒栖、拣遍枝柯。","生怜惜、弋人心眼，弯弓换却披蓑。","回峰路，遥夜影，伴孀娥。","楚山吴水经过。","费短鬓摩挲。","感星饭谋稻，水宿依荷。","唾壶击碎，惹骚客、横塞高歌。","惊人外、汉皋眠柳，京尘梦醒灵和。"]},{"t":"玉漏迟","f":"古风","c":["渡江烟树杳。","斜阳红罅，归飞饥鸟。","楚雁谋梁，三匝觅枝孤绕。","突见青帘招展处，皆醉侣、吟侪同调。","堪一笑。","主人迟客，停杯舒啸。","市楼酒绿灯红，想裙屐风流，止宜群少。","块垒浇除，讵是一杯能了。","老子分瓜深意，让纤手、惹人犀照。","银烛晓。","压酒吴姬来少。"]},{"t":"月下笛 冼玉清教授以蚝豉酥皮豆蓉饼杏仁饼鸡旦糕杂装一盒见贻。谱此代谢柬","f":"古风","c":["撑腹书虚，董肠醪薄，怎支吟力。","高歌堕帻。","听瓶笙，动茶癖。","胸中块垒蚝山结，换米帖、都成鸡肋。","惜花村沽远，调莺爇鸭，闭户秋寂。","门啄邮筒入。","睹巧月玲珑，腻云堆积。","酥醐味蜜，胡麻京样新出。","居然动我题糕兴，青鸟护、红巾密幂。","读饼说笑吴均，玉屑金泥仅识。"]},{"t":"霓裳中序第一 咏雩招饮寰乐园。用白石谱制词写怀，余亦继声","f":"古风","c":["离忧不客极。","欲涤愁肠思怎得。","吟损两肩耸力。","更枯叶瘦黄，寒风萧索。","閒偷一隙。","忘去鸿、离塞为客。","杯中月、山河寸影，总是可怜色。","秋寂。","烛光摇壁。","袅絮思、霓裳暗织。","狂评棋局往迹。","我欲乘风，卿缓归陌。","管弦虫韵息。","漫错认、池临凝碧。","南云望、中原如发，不觉弁哦侧。"]},{"t":"眼儿媚 为唐孝坚题山水立幅","f":"古风","c":["逢著青山足勾留。","何必买山谋。","秋林半翠，夕阳余紫，身在桥头。","知还倦鸟归飞急，前路任悠悠。","有人告我，亭空无客，我欲三杯。"]},{"t":"虞美人 六禾称病谢客，不忘填词。依调慰之","f":"古风","c":["茂陵秋雨文园老。","偶尔慵修稿。","偎衾搔背倩麻姑。","为问维摩丈室散花无。","人言酒是长生药。","休浪辞杯杓。","客嘲宾戏钓诗钩。","拟仿陈琳驰檄愈瞒头。"]},{"t":"虞美人·许直臣县长示我感时长歌，读毕书后，却寄","f":"古风","c":["虹霓壮吐胸中气。","血泪斑斓字。","哀弦变徵不成声。","莫认转移别调学风筝。","鸡长风雨天如晦。","魑魅逢人侮。","世间醒醉尽由他。","奈我肝肠得酒露槎枒。"]},{"t":"秋思耗","f":"古风","c":["吟帽当檐侧。","辄南山雷起，破轰晨色。","云路散花，玉壶投矢，天地都窄。","看眉蹙青山。"]}]};